INSERT INTO "public"."house" VALUES (11000010073, 1, '整租·北门口村住房 1室1厅1卫', 'whole_rent', 1, 3, '1室1厅1卫', 'one', 'west', 36.00, 1700.00, '房子图片真实，物业这点保证<br>毕业季：月付，押一付一，减轻前期经济压力<br>房子特点：全新家具家电，实墙隔音效果好<br>更注重隐私<br>我们是非常注重客户体验的，房间内家具家电齐全（含洗衣机、冰箱、沙发、床、衣柜、抽油烟机、独立卫生间）入室保洁及随时的快递收代发服务，更有专业贴心的物业服务。<br>楼内楼外监控无死角，物业统一管理安全保障、干净卫生，到地铁站非常方便，房间都是全新家具家电<br>【温馨提示】<br>我们都是物业没有任何的费用。<br>【配套】<br>1.公寓楼下超市<br>2.公寓楼下地铁站<br>3.免费咖啡厅<br>4.免费健身房<br>5.宜家家居家具。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/3581e12a419149eb84ed484623288019.jpg', '["bitehouse/3581e12a419149eb84ed484623288019.jpg", "bitehouse/8f6e49b29b9d4d5fad4266f23af90d42.jpg"]', 35, '北京', 434, '通州', '北门口村住房', '10号楼1单元10103室', 116.5507920, 39.7654450);
