INSERT INTO "public"."house" VALUES (11000010343, 1, '整租·禹州朗廷湾 3室1厅2卫', 'whole_rent', 8, 11, '3室1厅2卫', 'three', 'south', 88.00, 5640.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>所属区域是通州区，位于，附近是北关商圈。<br>【户型面积】<br>3室1厅2卫，100平米，南北朝向，带电梯。<br>【家具家电】<br>出租温馨舒适房源，配备齐全家具家电，尽享便捷生活。冰箱、洗衣机、热水器等家电一应俱全，沙发、可做饭等家具舒适实用，宽带、油烟机、燃气灶等配套设施，让您居住无忧。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括悦满街生活超市、范庄*生鲜超市等超市，以及距离北京远洋乐堤港仅1953米的购物中心。此外，还有惠兰美居公园、通州商务园等多个公园，以及首都医科大学附属北京友谊医院(通州院区)为您的健康保驾护航。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/4ec767fb0eeb4583a937b0c60c0dcd84.jpg', '["bitehouse/4ec767fb0eeb4583a937b0c60c0dcd84.jpg", "bitehouse/d2759cb07e484f7ea923a0c51c2b817f.jpg"]', 35, '北京', 434, '通州', '禹州朗廷湾', '11号楼2单元20404室', 116.6628750, 39.9406510);
