INSERT INTO "public"."house" VALUES (11000010417, 1, '整租·金隅汇星苑 3室1厅1卫', 'whole_rent', 6, 29, '3室1厅1卫', 'three', 'south', 88.00, 6750.00, '【交通出行】以为主要交通道路，方便进出四五环，6号线青年路，8通线高碑店站，出行方便。汇星苑的位置不错，紧靠，公交车站较多，有多条公交线路120支、350、499、494、306、831、834、835、486、858、991、运通111等10余条公交路线途经【周边配套】成熟大社区对应的设施齐全：多处活动广场、室内运动场馆、多家便民超市；外部-多条公交线路在园区停靠、民航总医院、3家大型综合超市、园区便民菜市场、免费开放的兴隆公园【小区介绍】小区是2016年的新社区，金隅开发的小区也是自己金海燕的物业', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c48300c6ad884c648083f5e57bff3477.jpg', '["bitehouse/c48300c6ad884c648083f5e57bff3477.jpg", "bitehouse/5a0a015c18f6470ebd9512526e24522c.jpg"]', 35, '北京', 428, '朝阳', '金隅汇星苑', '17号楼3单元30403室', 116.5361710, 39.9212390);
