INSERT INTO "public"."house" VALUES (11000010468, 1, '省心租·世茂维拉 1室1厅1卫', 'worry_free_rental', 5, 11, '1室1厅1卫', 'one', 'south', 59.00, 2950.00, '房源特色<br>1.房屋亮点<br>房源亮点存在主观性，请以实际看房为准<br>2.户型介绍<br>本房为整租房源，户型为1室1厅1卫，建筑面积为59.89平米，朝向为南。<br>3.交通出行<br>广阳城(房山线)；<br>4.周边配套<br>世茂维拉正规一居室好楼层。<br>5.小区信息', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7a3bef9851474268a564a7206603a3e4.jpg', '["bitehouse/7a3bef9851474268a564a7206603a3e4.jpg", "bitehouse/5378f6719e92475b8e9cf3c19c374c2c.jpg"]', 35, '北京', 433, '房山', '世茂维拉', '4号楼1单元10304室', 116.1775270, 39.7432240);
