INSERT INTO "public"."house" VALUES (11000010528, 1, '省心租·东亚尚品台湖 1室1厅1卫', 'worry_free_rental', 8, 17, '1室1厅1卫', 'one', 'west', 37.00, 2500.00, '通11路（董村—通州北苑口）早05:40-晚22:30<br>通7路（台湖—京东驾校）早07:00-晚22:30<br>临8路（大地站—地铁潞城站）早05:00-晚22:00<br>566公交直达（胡家垡—地铁万盛东）早05:00-晚22:30<br>地铁7号线黑庄户站<br>200米内公交566路，通7路<br>美食，小区楼下配有6家饭店（东北菜，北京菜，川湘菜，火锅，拉面馆，快餐外卖）<br>购物，楼下配有便利蜂，华联、水芭蕉，附近有大型绿品超市和家乐福。<br>医疗，楼下有药店，500米台湖卫生院。<br>教育，小区附近配有两所大型幼儿园，白水晶、明日星幼儿园，台湖新城职业学院。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/592944495cce4970b2d6412f21e1b850.jpg', '["bitehouse/592944495cce4970b2d6412f21e1b850.jpg", "bitehouse/b098a382ccdc4ac59b1654a9e7272e0a.jpg"]', 35, '北京', 434, '通州', '东亚尚品台湖', '10号楼1单元10404室', 116.6203880, 39.8358470);
