INSERT INTO "public"."house" VALUES (11000010554, 1, '省心租·新城嘉园 2室1厅1卫 有地铁', 'worry_free_rental', 3, 23, '2室1厅1卫', 'two', 'south', 79.00, 4350.00, '梨园地铁站新城家园精装两居室，出小区就是地铁旁边购物方便，贵友大厦小吃街一条街', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ff74b7bd38dd49f98e2d43eeafda1ab2.jpg', '["bitehouse/ff74b7bd38dd49f98e2d43eeafda1ab2.jpg", "bitehouse/c79d945e1dfb4b228d86b714a71a2715.jpg"]', 35, '北京', 434, '通州', '新城嘉园', '13号楼1单元10302室', 116.6710620, 39.8796290);
