INSERT INTO "public"."house" VALUES (11000010602, 1, '省心租·酒仙桥十二街坊 2室1厅1卫', 'worry_free_rental', 1, 6, '2室1厅1卫', 'two', 'south', 55.00, 6000.00, '房源描述1、房子照片都是真实照片，都是我亲自拍的<br>2、里面家具齐全，都是业主精心挑选配置的质量您放心<br>3、房子您看上了，保证给您个满意的<br>4、这是一个成熟的社区，小区环境很好，优雅安静，健身器械齐全交通也很方便并且公交站在不远处，出行便捷<br>5、紧邻大型，购物方便各大、餐饮、娱乐休闲场一应俱全，让您的日常生活特别便利<br>可能此房信息不够详细，如有任何问题，我会详细、耐心的为您解答<br>如果此房您不满意，请与我联系，我会根据您的需求，<br>当前市场价位，给您找到合适的社区，合适的房子<br>从千百个房源帖子中，您能选择我，是咱们的缘分', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/60646cc4274c46c8b60de674a88cd3b7.jpg', '["bitehouse/60646cc4274c46c8b60de674a88cd3b7.jpg", "bitehouse/7e097d3e923b499d88eb8fc8b4fe3ee1.jpg"]', 35, '北京', 428, '朝阳', '酒仙桥十二街坊', '7号楼1单元10104室', 116.4935670, 39.9602290);
