INSERT INTO "public"."house" VALUES (11000010607, 1, '整租·万科红 3室1厅1卫 精装修', 'whole_rent', 15, 17, '3室1厅1卫', 'three', 'south', 98.00, 10700.00, '1.万科红位于南三环外南四环内，紧邻地铁宋家庄站，5号线，10号线，亦庄线交界处<br>2.属于高品质小区，万科开发，万科物业直管，2013年交房入住，环境优美，安全性高24小时保安系统。民用水电，集中供暖。<br>3.周边生活配套齐全，首开福茂商厦，幸福超市，京客隆超市，，肯德基，正华电影院，各个商家餐厅。生活非常方便，配套设施齐全。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/358bfdc3f759462290adc099f7da663e.jpg', '["bitehouse/358bfdc3f759462290adc099f7da663e.jpg", "bitehouse/6c631a39f31240809c3cee69ab3ebd27.jpg"]', 35, '北京', 429, '丰台', '万科红', '7号楼3单元31202室', 116.4296580, 39.8462340);
