INSERT INTO "public"."house" VALUES (14010010076, 1, '个人房源·颐和家园 1室1厅1卫 无中介费', 'personal_house', 8, 22, '1室1厅1卫', 'one', 'south', 40.00, 800.00, '房屋亮点:押一付一配套齐全精装修<br>房源描述房屋亮点：（无中介）【配套齐全】【精装修】<br>房源描述：【价格便宜】【真实图片】<br>1、房子里干净，采光好，小区物业高端，管理完善。<br>2、适合住家，高端配置。<br>3、小区环境好，治安管理完善。<br>4、房源优势：精装全齐，配套设施齐全，附近有银行，大型超市，购物广场！<br>5、租金便宜：房子是精装特别干净，本人业主很好说话，房子可以长期租住，房子价钱还可以商量', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/dd98ddb462af40478e396f986c30be50.jpg', '["bitehouse/dd98ddb462af40478e396f986c30be50.jpg", "bitehouse/9a23a02af886498bb01eff59ba227d24.jpg"]', 49, '太原', 626, '小店区', '颐和家园', '3号楼2单元20703室', 112.6160150, 37.8004440);
