INSERT INTO "public"."house" VALUES (14010010112, 1, '整租·奥林匹克花园(南区) 1室1厅1卫', 'whole', 14, 28, '1室1厅1卫', 'one', 'east', 39.00, 1100.00, '房源描述1、地理位置优越，靠近迎泽西大街，西客站2、公交线路方便，出行顺畅，上下班方便3、周边配套设施齐全，美特好、菜市场、下元商贸购物便利，节省您的宝贵时间4、小区环境优美，宁静和谐，好环境总会给人带来好心情5、房子干净整洁，温馨舒适，窗明几净，就等您拎包入住6、家电家具齐全精装修，宽敞明亮，布局大方，采光特别好7、价格可商量，付款方式灵活如您有需要，我还负责周边小区奥林匹克花园、西华苑、辰憬家园、德馨花园、迎泽世纪城、小井峪、华清苑、华峪小区等成熟小区，竭诚为您服务', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/070cbb270335490e96c7567a4924c3a3.jpg', '["bitehouse/070cbb270335490e96c7567a4924c3a3.jpg", "bitehouse/8aedabcb2af64951a7f9d8d354cefedc.jpg"]', 49, '太原', 630, '万柏林区', '奥林匹克花园(南区)', '5号楼3单元30904室', 112.4786460, 37.8517500);
