INSERT INTO "public"."house" VALUES (14010010132, 1, '整租·南寒圣都 2室1厅1卫 拎包入住', 'whole', 26, 29, '2室1厅1卫', 'two', 'south', 97.00, 1300.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于万柏林区迎泽大街，西客站商圈。<br>【户型面积】<br>该房源是2室1厅1卫的南向户型，面积约为97平，带电梯，舒适宜居。<br>【家具家电】<br>出租房源提供热水器、宽带、沙发等舒适设施，还配有燃气灶和油烟机，方便您烹饪美食。<br>【周边配套】<br>该小区周边商业配套丰富，距离南寒商贸城614米，黎氏阁生活广场1264米，佳源超市(南寒圣都店)142米，钰皓百货279米等。附近有南寒公园、西环游园、北寒公园等公园，距离南寒购物广场976米。此外，还有山西医科大学第二医院(西院区)、中铁十二局集团中心医院、西山煤电集团职工总医院等综合医院，距离分别为771米、1242米、1362米。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/06065afe5b304f3f8f7f95959c47268d.jpg', '["bitehouse/06065afe5b304f3f8f7f95959c47268d.jpg", "bitehouse/4725264965ca4844a0d8a3aedc6a8706.jpg"]', 49, '太原', 630, '万柏林区', '南寒圣都', '2号楼3单元31003室', 112.4680240, 37.8540860);
