INSERT INTO "public"."house" VALUES (15010010049, 1, '个人房源·恒大城北区(商住楼) 1室1厅1卫 拎包入住', 'personal_house', 17, 23, '1室1厅1卫', 'one', 'north', 51.00, 2250.00, '城市之光公寓出租，豪华装修，家电家具齐备，拎包即可入住，紧邻地铁2号线一家村地铁站，出行方便', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ac002bf58a8e472688f0cc1a2ce1fc15.jpg', '["bitehouse/ac002bf58a8e472688f0cc1a2ce1fc15.jpg", "bitehouse/da3fb71cf4b542a39414ad1dd8312892.jpg"]', 60, '呼和浩特', 743, '新城区', '恒大城北区(商住楼)', '12号楼1单元10801室', 111.7213570, 40.8585680);
