INSERT INTO "public"."house" VALUES (15010010065, 1, '公寓·蓝色港湾 1室1厅1卫 精装修', 'apartment', 6, 24, '1室1厅1卫', 'one', 'south', 38.00, 1250.00, '房屋亮点配套齐全精装修<br>房源描述<br>房屋温馨干净整洁采光好，包暖包物业，家具家电齐全，拎包入住，适合住家.陪读.上班.年轻人入住，<br>小区地理位置优越，交通方便，周边辐射广，医院.超市.银行.幼儿园.商场，电影城，各类服务设施都非常完善.房源描述买房卖房庆鼎帮忙<br>满足人们的购房需要<br>房源描述：<br>1、繁华地段超值房源。<br>2、户型好：让您时刻感受温暖的阳光。<br>3、价格优：急租房源，价格超低。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/0e38ff16b275478a9d3667d46396f229.jpg', '["bitehouse/0e38ff16b275478a9d3667d46396f229.jpg", "bitehouse/3febd5987d7c490c9bca5104dc828cb8.jpg"]', 60, '呼和浩特', 745, '玉泉区', '蓝色港湾', '4号楼1单元10301室', 111.6717160, 40.7657440);
