INSERT INTO "public"."house" VALUES (15010010077, 1, '个人房源·万豪名园 4室1厅2卫 可月付', 'personal_house', 5, 18, '4室1厅2卫', 'four', 'south', 38.00, 1130.00, '【无中介】<br>我们和你一样，拒绝中介。<br>【房间详情】<br>设计师根据现代人喜好打造的清新舒适的“互联网+”长租白领公寓。室内配套标配床、床垫、衣柜、桌椅、智能门锁、挂衣钩、壁画、空调、洗衣机、冰箱和厨房等。每周一次保洁，高端化管家服务，只为下班后的你住的安心、住的舒心。<br>【周边设施】<br>九成房源小区门口有公交地铁站，周边西餐厅、各种随时叫外卖的中餐厅，公园，影院，KTV，菜市场和学校，运动场环绕其中，生活两不误…<br>【温馨提示】', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/223086e30b7c4ec8bc2da0f70470a290.jpg', '["bitehouse/223086e30b7c4ec8bc2da0f70470a290.jpg", "bitehouse/db8985819c1c46b2b7aafb3c012c94c1.jpg"]', 60, '呼和浩特', 746, '赛罕区', '万豪名园', '13号楼3单元30403室', 111.7120780, 40.7827060);
