INSERT INTO "public"."house" VALUES (15010010079, 1, '省心租·万达广场(A区) 4室0厅2卫', 'worry_free_rental', 3, 34, '4室0厅2卫', 'four', 'south', 35.00, 600.00, '万达广场步行街合租屋诚信出租，精装修，卫生干净，专人保洁阿姨打扫，无线网宽带，配套完善，家具家电齐全。可短期月付。步行地铁站200米。交通便利。愿意为漂泊在外的你寻找一个温家。1、步行200米直达地铁处，公交便利，出行方便。2、可短期月租，押一付一，付款方式灵活，无压力。3、专人保洁打扫，卫生干净，智能门锁，安全便捷。生活配套设施完善，快捷方便。4、单间合租价格500—1350价格不等，选择多样，随时看房，当天即可拎包入住。5、费用透明，无其他隐藏条款。房租无人为损坏，押金人走及退。', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/622b7c5630f3427b84531a0d6f111d4e.jpg', '["bitehouse/622b7c5630f3427b84531a0d6f111d4e.jpg", "bitehouse/d1685e463a1947b4857b841efda3c411.jpg"]', 60, '呼和浩特', 746, '赛罕区', '万达广场(A区)', '16号楼2单元20103室', 111.7340660, 40.8336920);
