INSERT INTO "public"."house" VALUES (15010010109, 1, '省心租·计委小区 1室1厅1卫 可短租', 'worry_free_rental', 1, 2, '1室1厅1卫', 'one', 'south', 30.00, 1630.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于新城区护城河南街，属于东落凤商圈。<br>【户型面积】<br>出租一套30平米的1室1厅1卫，南北朝向，步梯方便出行。<br>【家具家电】<br>出租房源提供热水器、宽带、厨房可做饭及油烟机等设施，舒适便利。<br>【周边配套】<br>此房源位于商业繁华地段，周边拥有火锅侠食材超市(计委大院店)、武秀珍超市、魔马鲜生航苑店、小军超市、航投购物中心等超市，满足您的日常购物需求。距离劝业场(昭乌达路店)716米，购物方便。周边还有将军衙署口袋公园、满都海公园等公园，距离内蒙古自治区人民医院717米、仁爱医院(昭乌达路)989米、内蒙古大学医院1064米等综合医院，为您提供健康保障。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/769e2ef5b4ef4ed7bcac753ef870eab5.jpg', '["bitehouse/769e2ef5b4ef4ed7bcac753ef870eab5.jpg", "bitehouse/6a2656b8ccc54e14be6124851ce8fc40.jpg"]', 60, '呼和浩特', 743, '新城区', '计委小区', '16号楼2单元20101室', 111.6989060, 40.8222960);
