INSERT INTO "public"."house" VALUES (15010010115, 1, '省心租·中海凯旋门 2室2厅1卫 拎包入住', 'worry_free_rental', 16, 29, '2室2厅1卫', 'two', 'south', 94.00, 2250.00, '手里灵活出租房源超多，家具齐全拎包入住。各个学校陪读房，欢迎致电联系<br>【房屋信息】<br>1、干净房屋出租,简单装修，不需打扫，拎包入住。<br>2、交通便利包暖包物业家具家电齐全随时看房居住舒坦安逸<br>3、周边生活设施齐全，商场、超市、菜市场、银行、学校等应有尽有！紧邻地铁2号线口，公交线路：26.85等<br>4、房子朝南，您只需买些生活用品即可拎包入住！机会稍纵即逝，不要和好房子再一次擦肩而过！<br>我承诺：我向您呈现的房屋真实存在的，房屋照片实地拍摄，对于房子的一切变化我们都会及时的跟进。<br>我承诺：不予虚假房源吸引客户；<br>我承诺：不予虚构房价招揽客户；', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b7904b94c4ce434eb77c93a9ac313e0e.jpg', '["bitehouse/b7904b94c4ce434eb77c93a9ac313e0e.jpg", "bitehouse/876429b8feb348ec94adca9d39f543aa.jpg"]', 60, '呼和浩特', 746, '赛罕区', '中海凯旋门', '3号楼2单元20602室', 111.7438310, 40.7946760);
