INSERT INTO "public"."house" VALUES (15010010133, 1, '公寓·闻都城市广场(商住楼) 1室1厅1卫 可短租', 'apartment', 18, 27, '1室1厅1卫', 'one', 'south', 31.00, 1600.00, '装修精美，拎包入住；前方视野开阔，无遮挡。落地飘窗，所以采光特别好；阳光充足，早晨的第一缕阳光直达，格局非常好，双卧室有效的隔离，很强的私密性，步行地铁站200米可直达，此房南北通透，格局相当漂亮，卧室和客厅是分离开的，所以采光特别好也特别好摆家具和电器。视野开阔，空气清新，紧对花园，特别适合居家过日子。清晨时，您站在客厅里，沐浴着旭日的光辉，精神饱满舒畅啊！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/985de9f256f047a5b44d7290c259e094.jpg', '["bitehouse/985de9f256f047a5b44d7290c259e094.jpg", "bitehouse/0b178fbc2aa8469596518203f746d504.jpg"]', 60, '呼和浩特', 745, '玉泉区', '闻都城市广场(商住楼)', '13号楼2单元20703室', 111.6823640, 40.7803430);
