INSERT INTO "public"."house" VALUES (21010010071, 1, '省心租·碧桂园太阳城(别墅) 2室1厅1卫 可月付', 'worry_free_rental', 7, 22, '2室1厅1卫', 'two', 'south', 23.00, 700.00, '【沈阳九区】大东区，和平区，铁西区，沈河区，皇姑区，于洪区，浑南区，沈北新区，均有房源<br>【押一付一】不绑定任何形式的贷款软件，不使用任何分期软件，房租直接打给公司<br>【租期灵活】部分房源有租期长短，均可选择，提供特殊情况，特殊处理<br>【家具电器】所有房源，家电齐全，冰箱，洗衣机，热水器。也有带空调的房间，电脑桌椅床衣柜齐全<br>【价格便宜】部分单间价格在400--1300元/月（因空间大小，朝向，装修定价)<br>【包含费用】只需要支付水电费，免物业费中介费卫生费<br>【免费带看】全程免费带看，免费提供入住，退房的服务，没有乱七八糟的东西<br>【售后保障】公司提供免费维修服务，只要不是恶意损坏，公司都会免费上门维修<br>【随时带看】24时电话在线，24时免费带看，只要打电话定好时间即可<br>【疫情防控】小区楼道，电梯，室内公共区域公司消毒除菌，人员登记，排除疫情感染者，安全', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/77d48cbaac1e4187a9a41fe504586178.jpg', '["bitehouse/77d48cbaac1e4187a9a41fe504586178.jpg", "bitehouse/ebd6a60e22f2425d800dd6032f8fc444.jpg"]', 72, '沈阳', 853, '沈北新区', '碧桂园太阳城(别墅)', '10号楼3单元30301室', 123.4241700, 41.9438100);
