INSERT INTO "public"."house" VALUES (23010010046, 1, '整租·中海云麓公馆二期 2室1厅1卫 拎包入住', 'whole', 14, 22, '2室1厅1卫', 'two', 'south', 98.00, 3050.00, '哈西范围内均有房源<br>所有房源均可押一付一部分房源押一付三<br>【电话在线,24h免费带看,<br>【客户必看一个电话一次可能一次客户一生朋友】<br>对于您的到来，深感荣幸。我从事房地产经纪行业多年，扎实的知识基础，是我赢得客户的基础。热情诚信的服务态度，让我和客户成为了要好的朋友。当您为了租房而头疼的时候，您不妨拿起电话，', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b8ebad1a5f4348598498dbd8e53a7d0d.jpg', '["bitehouse/b8ebad1a5f4348598498dbd8e53a7d0d.jpg", "bitehouse/1286d87a7cd64b26a907caa132de87e3.jpg"]', 95, '哈尔滨', 1007, '南岗区', '中海云麓公馆二期', '15号楼3单元30202室', 126.5797610, 45.6883640);
