INSERT INTO "public"."house" VALUES (31000010073, 1, '公寓·光迎路219号小区 1室1厅1卫', 'apartment', 9, 23, '1室1厅1卫', 'one', 'north', 27.00, 2054.00, '【周边配套】<br>交通：距离5号线奉贤新城站仅200米！门口奉贤新城公交枢纽，奉贤3路、11路、13路、37路，直达西渡、望园路、南桥汽车站、海湾等。拥有地下停车位，开车五mi上上海绕城高速和沪金高速。<br>购物：楼下龙湖上海奉贤天街，龙湖自持14万平大型商业综合体，已有永辉超市、星轶影城、星聚会KTV、MUJI无印良品、肯德基、、凑凑、桂满陇、捞王、华为、小米、OV、苹果等大牌进驻，畅享5mi生活圈。<br>生活：上海之鱼、泡泡公园、奉贤中心医院、奉贤中学等公园、医院、学校配套开车5mi即可达。<br>公寓内部：保洁服务、保安服务、管家服务、24小时监控、电子门锁、免费无线网、24小时提供娱乐公区健身房、会客厅、休息室、台球室、影音室、工具借用、紧急医药箱等。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/3015466d184d4ed1bef569ae2790899a.jpg', '["bitehouse/3015466d184d4ed1bef569ae2790899a.jpg", "bitehouse/a12fa1ba19aa44e380406dac4d5af7e9.jpg"]', 108, '上海', 1145, '奉贤', '光迎路219号小区', '14号楼3单元30302室', 121.4985020, 30.9134070);
