INSERT INTO "public"."house" VALUES (31000010123, 1, '整租·九亭U天地 1室1厅1卫 有地铁', 'whole_rent', 1, 18, '1室1厅1卫', 'one', 'south', 35.00, 3050.00, '本人发布的所有房源承诺真实有效，ZU无中JIE无差价，选择我“我专心用心，你安心放心”<br>1.环境干净整洁，住着温馨舒适，正气户型，采光通风充足<br>2.户型敞亮，楼层好，客厅挑高、宽敞舒适<br>3.精装修，家具配套齐全，看房预约，拎包即住<br>4.房间配置：家里配有家具，暖气，热水器，空调，洗衣机，冰箱，电视，床等基础家电配套齐全！<br>5.房间采光非常的棒，冬暖夏凉，舒适的不得了<br>6.地理位置优越，临近地铁站，公交站，生活便利，交通出行方便。<br>社区介绍：社区环境好环境优美适宜居住人文素质高物业管理完善', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8766afb285a54fb9941d715e9d552665.jpg', '["bitehouse/8766afb285a54fb9941d715e9d552665.jpg", "bitehouse/4a5669c930f1487983e5f37e358fb0c6.jpg"]', 108, '上海', 1143, '松江', '九亭U天地', '10号楼3单元30104室', 121.3253040, 31.1392800);
