INSERT INTO "public"."house" VALUES (31000010165, 1, '整租·沁秋小区 2室1厅1卫', 'whole_rent', 2, 6, '2室1厅1卫', 'two', 'south', 59.00, 5150.00, 'APP不常上，可直接电话联系沟通看房！<br>北新泾租赁房价：<br>合租基本上在2000~3000之间。<br>一房基本上在3500~6000之间。<br>两房基本上在4500~8000之间。<br>三房基本上在5800~10000之间。<br>租赁房价主要是看房子的装修程度，地理位置。<br>温馨提示：由于租赁市场交易频率比较快，有些时候对租掉的房源不能及时下架已租房源，敬请谅解哦如果想了解房源请直接电联，端口微聊可能不能及时回复！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a4dbe5ac4ba14329971a9051cb5560dc.jpg', '["bitehouse/a4dbe5ac4ba14329971a9051cb5560dc.jpg", "bitehouse/928e876903294a7cbf72ec64b1239929.jpg"]', 108, '上海', 1133, '长宁', '沁秋小区', '6号楼1单元10202室', 121.3617130, 31.2098550);
