INSERT INTO "public"."house" VALUES (31000010243, 1, '整租·江海新村 3室1厅1卫 拎包入住', 'whole_rent', 4, 6, '3室1厅1卫', 'three', 'south', 82.00, 2050.00, '1房屋周边有超市，菜市场，银行，便利店，<br>2环境好，周围的生活，教育，休闲娱乐，设施齐全，<br>3小区所处位置好，，交通便利，临近环城西路，近奉贤8路公交车，', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/44c61c7a58e040198b20c1da78c6b838.jpg', '["bitehouse/44c61c7a58e040198b20c1da78c6b838.jpg", "bitehouse/ee1316cfd3ee4c569cd9b3d11fa545d9.jpg"]', 108, '上海', 1145, '奉贤', '江海新村', '20号楼2单元20203室', 121.4546370, 30.9049040);
