INSERT INTO "public"."house" VALUES (31000010278, 1, '省心租·馨亭家苑(公寓住宅) 2室2厅2卫 拎包入住', 'worry_free_rental', 7, 9, '2室2厅2卫', 'two', 'south', 78.00, 5450.00, '房源详情1、户型比较好，采光也比较不错，房东人好，邻里和睦；<br>2、出小区门公交站上下班很方便；<br>3、生活便利超市银行商场一应俱全；<br>4、所在小区属于文明社区高素质好物业；<br>5、小区超高绿植率环境优美邻居和蔼友善在这里让你体会到家的温暖；6、诚心诚意为您服务；希望您在我这里能够找到适合自己的房子有家的感觉；', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/0adad7596e2d4a5da1d5ddb0fc4695ab.jpg', '["bitehouse/0adad7596e2d4a5da1d5ddb0fc4695ab.jpg", "bitehouse/ffebe51b9887482885d6798b285e9096.jpg"]', 108, '上海', 1143, '松江', '馨亭家苑(公寓住宅)', '13号楼3单元30301室', 121.3052840, 31.1484040);
