INSERT INTO "public"."house" VALUES (31000010280, 1, '省心租·萧塘尚乐苑 3室2厅2卫 随时可看', 'worry_free_rental', 22, 26, '3室2厅2卫', 'three', 'south', 120.00, 4288.00, '房子真实再租，实地核验已做！本人实拍照片视频欢迎您来实地看房！<br>如果您对这套房子感兴趣，可以私聊或者打电话咨询，我来一一为您解答。<br>这套房子您如果不满意，可以咨询我了解其他房子，本人手下房子非常多的，欢迎您的来电！！！！！！<br>房屋情况介绍<br>1、业主诚意出租此房，看房方便。<br>2、交通方便，为您的出行多一份保障，节省您宝贵的时间。<br>3、便利的购物场所是您生活的保障。<br>4、饮食环境是您生活的保障。<br>特别提醒', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/78fe2d9dcc854ed8822f504e6acbf69a.jpg', '["bitehouse/78fe2d9dcc854ed8822f504e6acbf69a.jpg", "bitehouse/7174145fcb6c4ac8bb254741dc809559.jpg"]', 108, '上海', 1145, '奉贤', '萧塘尚乐苑', '14号楼1单元11303室', 121.4394000, 30.9587570);
