INSERT INTO "public"."house" VALUES (31000010292, 1, '省心租·海尚菊苑(南区) 2室1厅1卫 有地铁', 'worry_free_rental', 3, 5, '2室1厅1卫', 'two', 'south', 73.00, 3850.00, '.1.房子采光级好楼层位置极好<br>2.房子是2室一厅，紧靠地铁口！<br>3.房东诚心出租..房子看中价格好谈<br>4.房源真实.照片真实.价格真实<br>如果这套不合适，只需给我打个电话，包您找房事半功倍，不管您要找哪里，怎样的价格，怎样的环境，保证帮您找到称心如意的房子<br>您的信赖就是我工作的动力，相信您的选择，期待您的来电<br>本人手里周边老房东委托的在租一房、两房、以及大面积的三室都有现房在出租状态。只要您一个电话.有钥匙可随时可看现房！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/1a412c720c684af99cbea2bfaa0a26e2.jpg', '["bitehouse/1a412c720c684af99cbea2bfaa0a26e2.jpg", "bitehouse/f3230c74097343daa4a017ce695049f5.jpg"]', 108, '上海', 1139, '宝山', '海尚菊苑(南区)', '14号楼1单元10102室', 121.3669540, 31.3535860);
