INSERT INTO "public"."house" VALUES (31000010294, 1, '省心租·培花久远公寓 1室1厅1卫 随时可看', 'worry_free_rental', 2, 6, '1室1厅1卫', 'one', 'south', 50.00, 4650.00, '房源优势：杜绝虚假只做视频以及更多照片请直接联系我<br>1、周边配套：菜市场、小吃、饭店、公园、商场、等。小区出门就是公园、有助于老年人休息和健身的活动场所.<br>2、随时看房：此房有钥匙，只要您一个电话随时带您去实地看房<br>3、房东心态：房东说自己体会过在外工作的艰辛、房子如果顾客看中价格还可以商量.<br>4、介绍:“始终坚持用爱对待客户、用真诚去赢得客户的信任与友情.<br>5、装修情况：本人实地看过此房，照片都是实体拍的，可拎包入住<br>爱心寄语：愿每一位租户都住的开心。放心，舒心。<br>温馨提示：', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e6f28649ade742f6abfbbcb5a480cb51.jpg', '["bitehouse/e6f28649ade742f6abfbbcb5a480cb51.jpg", "bitehouse/0f14ceb7bf9a454188759acc93429fab.jpg"]', 108, '上海', 1141, '浦东', '培花久远公寓', '3号楼1单元10103室', 121.5603030, 31.1955230);
