INSERT INTO "public"."house" VALUES (31000010336, 1, '省心租·禹洲蓝爵 1室1厅1卫', 'worry_free_rental', 20, 26, '1室1厅1卫', 'one', 'south', 45.00, 3242.00, '本人在金桥区域工作5年有余，主营6号线，9号线，12号线，14号线地铁附近的整租合租租赁业务。<br>出租各种单间和带独立厨卫的一室户。<br>单间：780--1980。<br>独立厨卫一室户：1980--4680。<br>整租：<br>一房一厅一厨一卫2580--4080。<br>二房一厅一厨一卫3080--5080。<br>三房一厅一厨一卫5080--8580。<br>其次可以根据您的预算和工作地点为您匹配合适的地铁附近房子，看房到地铁口我过去接您。房源真实可靠，均由本人实地拍摄！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/2499f6b566204338a4cea258cc95679e.jpg', '["bitehouse/2499f6b566204338a4cea258cc95679e.jpg", "bitehouse/29c2027a204942aaac2a7beb1feae916.jpg"]', 108, '上海', 1141, '浦东', '禹洲蓝爵', '12号楼1单元11803室', 121.6103400, 31.2571300);
