INSERT INTO "public"."house" VALUES (31000010366, 1, '省心租·齐贤雅苑 1室1厅1卫 随时可看', 'worry_free_rental', 2, 18, '1室1厅1卫', 'one', 'south', 58.00, 2080.00, '该房源位于金汇板块，临港新城大型居住区。价格便宜，错过就是损失<br>BRT快速公交直达8号线沈杜公路地铁站，小区旁边大型商业龙湖天街。小型菜市场，满足一站式购物，家门口出行500米<br>小区高绿化，栋距大采光充足。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ca0b49aded8f41dd970f9704ded15e7e.jpg', '["bitehouse/ca0b49aded8f41dd970f9704ded15e7e.jpg", "bitehouse/b1d1958718d4404e9fd5d650f8fc4746.jpg"]', 108, '上海', 1145, '奉贤', '齐贤雅苑', '11号楼3单元30204室', 121.5065750, 30.9606560);
