INSERT INTO "public"."house" VALUES (31000010382, 1, '省心租·宜浩佳园 1室2厅1卫', 'worry_free_rental', 1, 4, '1室2厅1卫', 'one', 'south', 77.00, 2400.00, '紧靠百联商场，房子南北通透户型，采光好通风好，全明户型，房子卫生干净整洁，随时看房领包入住，菜场、超市、公交车站都在小区门口，配套成熟，小区环境优美物业管理完善，学校有冰厂田幼儿园、明珠小学，实验中学，房源多多随时欢迎你的咨询。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e8da5e042e294208a4b3fed5d90dcbfc.jpg', '["bitehouse/e8da5e042e294208a4b3fed5d90dcbfc.jpg", "bitehouse/cfa0ecd344e244dbb05799b9bc7ff4c1.jpg"]', 108, '上海', 1141, '浦东', '宜浩佳园', '9号楼2单元20101室', 121.9111610, 30.9012250);
