INSERT INTO "public"."house" VALUES (31000010452, 1, '省心租·文苑小区(虹口) 1室1厅1卫 随时可看', 'worry_free_rental', 1, 6, '1室1厅1卫', 'one', 'south', 39.00, 3850.00, '小区地理位置好，位于商业圈，交通便利，出小区是公交站牌，小区设施配套齐全，菜市场，医院，超市。小区环境幽雅，绿化面积大，家里家电齐全，拎包入住！看房方便提前预约！欢迎致电。房源真实，图片真实，品质服务保证，若想了解其他房源，我也会成为您专业的置业顾问。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f7bd8fc0f59447f38c900a3ad146ecec.jpg', '["bitehouse/f7bd8fc0f59447f38c900a3ad146ecec.jpg", "bitehouse/f050bf5b0b0b41eb9da4cac844f8934c.jpg"]', 108, '上海', 1136, '虹口', '文苑小区(虹口)', '5号楼1单元10101室', 121.4659500, 31.2961480);
