INSERT INTO "public"."house" VALUES (31000010561, 1, '整租·永盛公寓 1室1厅1卫 随时可看', 'whole_rent', 3, 6, '1室1厅1卫', 'one', 'south', 45.00, 1850.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>所属区域是嘉定区，位于双单路718弄，附近是嘉定新城商圈。<br>【户型面积】<br>这套朝南的42平1室1厅1卫房源配有电梯，采光通风良好，为您提供舒适宜居的生活体验。<br>【家具家电】<br>出租温馨舒适房，配备冰箱、洗衣机、热水器等家电，宽带、沙发等家具，可做饭、油烟机、燃气灶一应俱全，让您享受便捷生活。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括石冈门塘休闲公园、马陆公园、紫气东来公园等公园，以及麦德龙(上海嘉定商场店)、OEA全屋定制超市、易购超市(希望路店)、龙大姐蔬果超市、福润生活超市(云谷路店)等超市，还有永润星辰休闲广场、中信泰富万达广场(嘉定新城店)、嘉定宝龙广场、大融城、吉宝绿地缤纷城等购物中心。居住在此，您将享受到便捷的生活。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/713366314da948fb957909ac82b1848d.jpg', '["bitehouse/713366314da948fb957909ac82b1848d.jpg", "bitehouse/a6f7db0bc99949b3b7dfd419056d7749.jpg"]', 108, '上海', 1140, '嘉定', '永盛公寓', '10号楼3单元30204室', 121.2644600, 31.3329070);
