INSERT INTO "public"."house" VALUES (31000010607, 1, '整租·虹延小区 2室1厅1卫 有地铁', 'whole_rent', 4, 5, '2室1厅1卫', 'two', 'south', 54.00, 6650.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于长宁区虹梅路3800弄,虹梅路3818弄，紧邻长宁周边商圈。<br>【户型面积】<br>这套2室1厅1卫的南北朝向房源，面积约为54平，是步梯房，为您提供舒适宜居的生活空间。<br>【家具家电】<br>出租房配备齐全，有冰箱、洗衣机、热水器等生活设施，还有宽带、沙发等舒适家居。厨房设施齐全，可做饭，有油烟机、燃气灶，让您生活便捷舒适。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括体汇+名都体育公园、滑板公园、延虹绿地、仙霞公园、水霞公园等公园，以及亮子生鲜、祝乐福、168生鲜、虹福好又多超市、拥军超市等超市，满足您的日常生活需求。此外，还有森晟世洋国际广场、九洲生活广场、星空广场、金汇四季广场等购物中心，为您提供购物、休闲、娱乐等多种体验。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/4b4ac14e1e78430da0fdcb11a8f69ea7.jpg', '["bitehouse/4b4ac14e1e78430da0fdcb11a8f69ea7.jpg", "bitehouse/7e613afd83264dbf8a26688beb6ca040.jpg"]', 108, '上海', 1133, '长宁', '虹延小区', '3号楼2单元20102室', 121.3852660, 31.1916420);
