INSERT INTO "public"."house" VALUES (31000010701, 1, '整租·民乐城丽水雅苑南苑 1室1厅1卫 有地铁', 'whole_rent', 12, 15, '1室1厅1卫', 'one', 'south', 51.00, 2050.00, '说的再好不如出来跑跑，图片再赞不如出来看看<br>一、房源基本信息：<br>1、户型优势：主卧朝南，厨卫朝北，南北通透<br>2、装修情况：干净整洁，房东自住，装修好空间大<br>3、房源位置：采光充足，小区花园、小区位置便利，房东人很好<br>4、周边配套：生活方便，上班出行方便<br>5、小区环境：小区内绿化覆盖面积大还有各种小公园有健身场所和设施，环境与运动结合有益身心健康！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/06e4158d1a214569a7271fb203dbeb0c.jpg', '["bitehouse/06e4158d1a214569a7271fb203dbeb0c.jpg", "bitehouse/33228b9a5dce4965bc8fbb9d3527133d.jpg"]', 108, '上海', 1141, '浦东', '民乐城丽水雅苑南苑', '8号楼1单元10804室', 121.7557210, 31.0673930);
