INSERT INTO "public"."house" VALUES (31000010703, 1, '整租·悦丰新苑 2室2厅1卫', 'whole_rent', 1, 6, '2室2厅1卫', 'two', 'south', 92.00, 3150.00, '本人承诺所发布的每一条房源均为！<br>此房本人实地看过，房东出租，暂无出售打算，寻找长期稳定客户！小区地理位置优越，交通便利，周边500米内有学校菜场超市车站商场。<br>若此房您不觉得满意，更多房源信息请点我的头像，您将您的详细需求告诉我，我会在短时间内为您选出适合您的家，不会浪费您的宝贵的时间。<br>温馨提示：由于租赁市场交易频率比较快，有些时候在租的房源不能及时下架已租房源，敬请谅解。如果想了解房源请致电，端口可能不能及时回复！<br>PS:1.公司房源共享，您一块区域只需要一位经纪人，以免电话太多打扰到您的生活，奉贤区靠谱的经纪人，请相信专业的力量！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/55825e0385694f3eaa6851be155af591.jpg', '["bitehouse/55825e0385694f3eaa6851be155af591.jpg", "bitehouse/438c8d2a98a341c4abf9d3642b80db05.jpg"]', 108, '上海', 1145, '奉贤', '悦丰新苑', '17号楼3单元30102室', 121.4494390, 30.9253930);
