INSERT INTO "public"."house" VALUES (31000010794, 1, '省心租·金地丰盛道 3室2厅2卫', 'worry_free_rental', 12, 18, '3室2厅2卫', 'three', 'south', 99.00, 5050.00, '此房源全为全新精装修，拎包入住。房间都非常干净清爽，房间空间也是比较大，房屋内的设施配套齐全，居住环境好，随时看房入住。可自己找人或者朋友，同事拼租或者合租…）以上房源可长租或者短租……价格看好可以面谈...周边交通设施配套齐全，有地铁九号线，大学城站，新城站，有轨电车公交车松莲B线等等交通非堂便，<br>小区周边设施：周边设施配套相对齐全，有万达广场，麦德龙，月星家具，富悦大酒店，大卖场，小学，等等。一个温馨的家，从一个电话开始......<br>[温馨提示]大多房源共享，一个区域寻找一位经纪人，以免电话过多影响您正常工作休息。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b6cd8e45988c4050b16f0cf28bd1dc73.jpg', '["bitehouse/b6cd8e45988c4050b16f0cf28bd1dc73.jpg", "bitehouse/8290c20135274a468ba13e290b20b25c.jpg"]', 108, '上海', 1143, '松江', '金地丰盛道', '19号楼1单元10602室', 121.2544800, 31.0625950);
