INSERT INTO "public"."house" VALUES (31000010798, 1, '省心租·申城佳苑一期A块 2室1厅1卫 拎包入住', 'worry_free_rental', 2, 6, '2室1厅1卫', 'two', 'south', 60.00, 4600.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于浦东区孙环路177弄，紧邻张江商圈。<br>【户型面积】<br>该房源为南向2室1厅1卫，面积约为60平，带步梯，方便出行。<br>【家具家电】<br>出租温馨舒适房，配备冰箱、洗衣机、热水器等家电，宽带、沙发等家具，可做饭、油烟机、燃气灶一应俱全，让您享受便捷生活。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，小区周边有邻世纪社区生活超市(高木桥店)、明康汇生鲜菜市(上海申城佳苑店)、清美鲜家(高木桥路店)、联华超市(张建店)、浦商生鲜(申城佳苑店)等超市，满足日常生活所需。此房源距离孙桥耀泓生活广场656米，距离高科商业广场1963米，购物便捷。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9e4d4878b1214168bb6678328bf0d1ac.jpg', '["bitehouse/9e4d4878b1214168bb6678328bf0d1ac.jpg", "bitehouse/37e2d15c170c48b8a9e38cc5b4754965.jpg"]', 108, '上海', 1141, '浦东', '申城佳苑一期A块', '17号楼2单元20103室', 121.6384750, 31.1859090);
