INSERT INTO "public"."house" VALUES (31000010816, 1, '省心租·肖塘路255弄小区 1室1厅1卫', 'worry_free_rental', 11, 15, '1室1厅1卫', 'one', 'north', 38.00, 1550.00, '房子真实再租，实地核验已做！本人实拍照片视频欢迎您来实地看房！<br>如果您对这套房子感兴趣，可以私聊或者打电话咨询，我来一一为您解答。<br>这套房子您如果不满意，可以咨询我了解其他房子，本人手下房子非常多的，欢迎您的来电！！！！！！<br>房屋情况介绍<br>1、业主诚意出租此房，看房方便。<br>2、交通方便，为您的出行多一份保障，节省您宝贵的时间。<br>3、便利的购物场所是您生活的保障。<br>4、饮食环境是您生活的保障。<br>特别提醒', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/131a5102b81e49b4a16630a26067cb0e.jpg', '["bitehouse/131a5102b81e49b4a16630a26067cb0e.jpg", "bitehouse/83937c2e1af5482da2d68a4b6e0bcdf8.jpg"]', 108, '上海', 1145, '奉贤', '肖塘路255弄小区', '11号楼1单元10301室', 121.4345110, 30.9613860);
