INSERT INTO "public"."house" VALUES (32010010023, 1, '合租·湖景花园 4室1厅4卫 有地铁', 'shared', 2, 18, '4室1厅4卫', 'four', 'south', 21.00, 960.00, '南京各区可以调换客房！<br>1、青年白领公寓，您的室友都是普通白领，给您良好的朋友圈<br>2、水电煤都是民用价，没有额外的收费<br>3、24管家贴心服务，公共区域定时保洁，专人负责房间设备的维护<br>4、宜家装修，生活设施齐全（空调、冰箱、洗衣机、微波炉等）样样俱全，拎包入住！全明户型，采光超好，入室给您家的感觉<br>5、小区门口就是地铁站（2号线地铁）公交站台、交通四通八达', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f961f9bed7a647dba989e4c7ef437633.jpg', '["bitehouse/f961f9bed7a647dba989e4c7ef437633.jpg", "bitehouse/a0e5e7b501ca438291d9ea26fa076a6e.jpg"]', 109, '南京', 1147, '玄武区', '湖景花园', '14号楼2单元20201室', 118.7909680, 32.0872750);
