INSERT INTO "public"."house" VALUES (32010010156, 1, '省心租·东虹花苑东苑 2室1厅1卫', 'worry_free_rental', 1, 6, '2室1厅1卫', 'two', 'south', 71.00, 2049.00, '本人主营：江宁三号线，一号线，S1号线机场线，上秦淮秣陵街道，东山万达，江宁大学城<br>五大放心：<br>不用担心找不到心仪房子<br>不用担心有乱七八糟用<br>不用担心到期房东不退押金<br>不用担心期间房租变动<br>不用担心房屋设施出现问题无人处理<br>1：免带看，免保洁<br>2：协助免无偿办住房补贴<br>3：支付灵活：可月付，季付<br>4：维修：家具家电损坏保修<br>5：全屋免宽带，上网无忧<br>6：照片视频为本人实地拍摄<br>7：暂不短租：一年或半年（少）起租<br>8：户型图或照片仅供参考，具体以实地为主', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b61c9b498511410b82947fe498e26302.jpg', '["bitehouse/b61c9b498511410b82947fe498e26302.jpg", "bitehouse/3fdeec90470e483baeaf33c3c8af9b84.jpg"]', 109, '南京', 1154, '江宁区', '东虹花苑东苑', '10号楼2单元20102室', 118.7756670, 31.8683150);
