INSERT INTO "public"."house" VALUES (32010010158, 1, '省心租·中南世纪雅苑二期 3室1厅1卫', 'worry_free_rental', 6, 22, '3室1厅1卫', 'three', 'south', 93.00, 3350.00, '1.精装修，拎包入住，基础设施完善(空调，洗衣机，热水器微波炉，电磁炉，电视机等)<br>2.南北通透，阳光充足，视野开阔，物业完善<br>3.周边商圈配套齐全，楼下就是超市，便利店，美食街、健身房，菜场等，生活方便，出行方便，公交站，地铁站紧密相连<br>4.家具电器损坏免费上门维修，油烟隔离、可做饭<br>5.周边住户都是年轻人，有朝气，无不正当职业<br>6.24小时保安，非常安全，智能门锁，快捷，方便<br>7.照片为本人实地拍摄，欢迎看房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/4a4442105b7f4c4cabb4f21674eb9c83.jpg', '["bitehouse/4a4442105b7f4c4cabb4f21674eb9c83.jpg", "bitehouse/f5ab7e7fc7044f9cb7e7cad08b4f9d88.jpg"]', 109, '南京', 1152, '栖霞区', '中南世纪雅苑二期', '13号楼2单元20604室', 118.9094040, 32.0376820);
