INSERT INTO "public"."house" VALUES (32010010186, 1, '省心租·长江时代雍澜悦府 4室1厅2卫 随时可看', 'worry_free_rental', 11, 26, '4室1厅2卫', 'four', 'south', 140.00, 7200.00, '随时看房，有车接送，真实价格，全网<br>1、精装修，拎包入住，基础设施完善(空调、洗衣机、热水器等)<br>2、南北通透，阳光充足，视野开阔，晒衣方便物业完善<br>3、周边商圈配套齐全，超市，医院，娱乐地铁站紧密相<br>连<br>4、提供保洁，家电器具损坏免费上门维修<br>5、住户素质高，一般都是上班族，无不正当职业<br>6、安全，智能，快捷，方便，高效租房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/0a34d89c00634f25a8bcd2ab7564f317.jpg', '["bitehouse/0a34d89c00634f25a8bcd2ab7564f317.jpg", "bitehouse/7bdd6926bfcc4c45a53cbf620c2abdc7.jpg"]', 109, '南京', 1151, '浦口区', '长江时代雍澜悦府', '10号楼2单元20902室', 118.6557380, 32.0726580);
