INSERT INTO "public"."house" VALUES (32010010206, 1, '省心租·仁锦苑(E区) 3室1厅1卫 可短租', 'worry_free_rental', 16, 26, '3室1厅1卫', 'three', 'south', 90.00, 1800.00, '周边设施齐全，方便购物消遣，靠近公交站台，地铁站，<br>交通出行也很便利<br>【房型特点]房型好，客厅主卧朝南，采光超棒，户型设计合理，没有浪费面积。主卧室宽大，家具可任意摆设，客厅整洁明亮，空气流通性好，对身体健康非常有益。【装修优势]房子装修好，装修设计细致实用，干净清爽，温馨舒适，居家设施齐全，保养的很到位。[物业环境]<br>物业比较好，管理比较到位，让你感觉到真正是回到了家!!小区周围娱乐项目应有尽有，让您的生活充满乐<br>趣!收起<br>冰箱洗衣机热水器宽带<br>沙发油烟机燃气灶可做饭<br>电视空调衣柜床<br>卫生间智能门锁阳台暖气<br>x电磁炉x微波炉橱柜<br>提问<br>在线聊打电话', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9af9151360eb4ed2ba68bcaac06d0438.jpg', '["bitehouse/9af9151360eb4ed2ba68bcaac06d0438.jpg", "bitehouse/3319a31d37ad46589da7d0d28836d6f9.jpg"]', 109, '南京', 1155, '六合区', '仁锦苑(E区)', '6号楼1单元10201室', 118.7257740, 32.2241380);
