INSERT INTO "public"."house" VALUES (32010010209, 1, '整租·腾飞园 2室1厅1卫 拎包入住', 'whole', 3, 6, '2室1厅1卫', 'two', 'south', 82.00, 4600.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>所属区域是鼓楼区，位于龙园中路，附近是龙江商圈。<br>【户型面积】<br>这套南向的2室1厅1卫房源，面积82平，步梯房，为您提供舒适的居住体验。<br>【家具家电】<br>出租温馨舒适房，配备冰箱、洗衣机、热水器等家电，宽带、沙发等家具，让您尽享便捷生活。厨房设施齐全，可做饭、油烟机、燃气灶一应俱全，满足您的各种需求。<br>【周边配套】<br>天盛广场附近的该小区，周边拥有丰富的商业配套。距离金盛百货(天盛广场店)仅662米，距离新城市广场(草场门大街店)726米。此外，还有原加源生活优选超市(月光店)、京致生鲜超市、苏果超市(宝地园特许店)、龙江百货超市、天翼广场等超市，满足您的日常购物需求。此外，还有天盛广场、阳光广场-综合楼、古林公园、古林公园-东大门售票处、郑和宝船厂遗址公园、南京国防园等公园，让您尽享休闲时光。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/5dd043a1b62446f29868b9b216bb5cc1.jpg', '["bitehouse/5dd043a1b62446f29868b9b216bb5cc1.jpg", "bitehouse/b62bdb61500143b980d03d8e655a685d.jpg"]', 109, '南京', 1150, '鼓楼区', '腾飞园', '3号楼3单元30102室', 118.7464910, 32.0608800);
