INSERT INTO "public"."house" VALUES (32010010212, 1, '省心租·金王府小区 1室1厅1卫 有地铁', 'worry_free_rental', 1, 6, '1室1厅1卫', 'one', 'south', 25.00, 2000.00, '房源描述1、精装修，家电齐全，拎包入住，基础设施完善（床、空调、书桌、座椅、衣柜、热水器、洗衣机、冰箱等）：全新家具，品牌家电，提高生活品质<br>2、南北通透，阳光充足，视野开阔，物业完善<br>3、周边商圈配套齐全，超市，菜场、公交、的士、滴滴和停车位<br>4、免费服务：免费WiFi，GEE极速宽带家电器具免费预约，上门维修<br>5、主打青年品质住房，住户素质高，都是上班族，无不正当职业<br>6、温馨的床和舒适的桌椅，睡觉、发呆、看书、玩游戏都特棒<br>7、安全，智能，快捷，方便，高效租房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/986361a51f194709b07f16dae96eb8b9.jpg', '["bitehouse/986361a51f194709b07f16dae96eb8b9.jpg", "bitehouse/f6da7beda1434ea6a732d0ef490b0777.jpg"]', 109, '南京', 1154, '江宁区', '金王府小区', '17号楼1单元10101室', 118.8235910, 31.9497150);
