INSERT INTO "public"."house" VALUES (32050010002, 1, '合租·太阳星辰花园湖邑 1室1厅1卫 可月付', 'shared', 14, 23, '1室1厅1卫', 'one', 'south', 30.00, 850.00, '欢迎咨询岳岳为您找房房源不止一套附近多套可选1/5号线地铁口的房子<br>主做板块斜塘小区：莲花新村、莲香新村荷韵新村、敦煌小区、中南锦苑，金辉尊域海德、翰林缘、星湖名轩、蝴蝶湾、荣域花园，淞泽家园，文荟苑，文荟人才公寓，橄榄湾、中旅蓝岸国际，菁英公寓，湖东Cbd小区：中海国际、枫情水岸、凤凰城、路劲主场，东湖大郡、星公元名邸，水墨三十度，中海一到八区，第五元素，东湖林语，<br>湖畔天城，自由水岸，东湖大郡，九龙仓，太阳城，湖滨一号，中央景城，翡翠国际，玲珑湾，海尚壹品，雅戈尔，绿地华尔道，紫荆苑，和风雅致', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/23188575f48c4eef90c153a6d1bccd2e.jpg', '["bitehouse/23188575f48c4eef90c153a6d1bccd2e.jpg", "bitehouse/d509a9a2a9a748bcb484620d12818fae.jpg"]', 113, '苏州', 1182, '吴中区', '太阳星辰花园湖邑', '19号楼1单元10502室', 120.7657410, 31.3320580);
