INSERT INTO "public"."house" VALUES (32050010150, 1, '整租·文昌花园 2室2厅1卫 精装修', 'whole', 1, 18, '2室2厅1卫', 'two', 'south', 87.00, 2650.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于高新区文昌路301号，浒墅关商圈。<br>【户型面积】<br>该房源为南向2室2厅1卫，面积87平，带电梯。<br>【家具家电】<br>出租房源提供齐全家具家电，包括冰箱、洗衣机、热水器等生活设施，以及沙发、可做饭区域和油烟机、燃气灶等厨房设备。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括优乐鲜生鲜超市店、88超市(文昌店)等超市，以及奇力康皮肤健康园大润发超市等购物中心，如兴贤商业广场、汇金广场(兴贤路店)等。此外，还有大白荡城市生态公园、虎丘区真山公园等公园，以及苏州大学附属第二医院(浒关院区)综合医院，为您提供便捷的生活所需。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/32292f2cae0e4ba598141a7a2d891caa.jpg', '["bitehouse/32292f2cae0e4ba598141a7a2d891caa.jpg", "bitehouse/d263723ef8de4b81a1873f8446c01ad5.jpg"]', 113, '苏州', 1181, '虎丘区', '文昌花园', '2号楼3单元30101室', 120.5061010, 31.3680530);
