INSERT INTO "public"."house" VALUES (33010010016, 1, '合租·丽晶国际中心 2室2厅2卫 可月付', 'shared', 8, 39, '2室2厅2卫', 'two', 'south', 15.00, 1350.00, '很荣幸您能打开我的帖子！<br>点击我的头像查看更多适合自己的房子！<br>房屋全部精装修，家具家电齐全，房间拥有200兆宽带高速上网！<br><br>小区24小时不间断安保巡逻，出入小区人脸识别！<br>【服务】<br>本公司所有房屋可月付！可免费维修室内家具家电！我们团队拥有完整的售后体系，我们专业的业务员为您提供服务，有问题全程为您解答！并帮助您向房东讲的价格！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/d6fd965353314660ac88be2154377e07.jpg', '["bitehouse/d6fd965353314660ac88be2154377e07.jpg", "bitehouse/7473e0f53b20473ab314f5b0c6b01718.jpg"]', 122, '杭州', 1246, '萧山区', '丽晶国际中心', '6号楼3单元30402室', 120.2462840, 30.2416880);
