INSERT INTO "public"."house" VALUES (33010010122, 1, '整租·亭山万和府 3室2厅2卫', 'whole', 1, 24, '3室2厅2卫', 'three', 'south', 120.00, 1950.00, '1.房子干净舒适，基本生活家电齐全；拎包即可入住；<br>2.附近生活配套设施到位，有菜场、银行、车站、地铁等；<br>3.装修清爽，采光无遮挡；通风效果好；<br>4.随时入住方便，房间内很干净，无异味;<br>5.看房方便有钥匙，只需您一个电话，约好时间即可;<br>6.如对该房屋有兴趣或疑问，请致电，以便为您解答;<br>7.租后服务，请您放心，热情、诚信、专业是我赢得客户信任的基础;<br>上述面积均为建筑面积，还要以房东房产证上实际面积为准；', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c2d5d19131294b7a962aa43390977dd8.jpg', '["bitehouse/c2d5d19131294b7a962aa43390977dd8.jpg", "bitehouse/96c9c54604174a7ba8e800b0c3f30d59.jpg"]', 122, '杭州', 1248, '富阳区', '亭山万和府', '3号楼3单元30102室', 119.9973470, 30.0032780);
