INSERT INTO "public"."house" VALUES (34010010006, 1, '整租·旭辉翡翠江来 3室2厅1卫 随时可看', 'whole', 5, 18, '3室2厅1卫', 'three', 'south', 111.00, 1530.00, '有钥匙欢迎随时预约看房，房子周边生活设施齐全，交通方便<br>视野开阔阳光充足！<br>家具家电齐全，拎包入住！<br>温馨提示：这套房不适合您，欢迎联系我发其他房源。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/43e556a5569c4765bced95375d4dcd1e.jpg', '["bitehouse/43e556a5569c4765bced95375d4dcd1e.jpg", "bitehouse/4df96488c6314eb7a0fc5069c63278b0.jpg"]', 133, '合肥', 1338, '肥西县', '旭辉翡翠江来', '11号楼3单元30404室', 117.1582800, 31.7351660);
