INSERT INTO "public"."house" VALUES (34010010044, 1, '公寓·站水万洋科技倒班宿舍 1室1厅1卫 可短租', 'apartment', 5, 6, '1室1厅1卫', 'one', 'south', 50.00, 1051.00, '1、酒店式单身公寓，精装修朝南一室，免费停车，拎包入住！<br>2、出行便捷，配套齐全，更有小吃街尽享美食，品质生活从此开启！<br>3、无论您是过来上班、还是过来创业或者是找工作，选择一套您喜欢的精装一室，让您下班回家后感受家的温暖，褪去一天的疲惫，愿您每次租房都不是颠沛流离，而是新的开始。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b954da87a0c043e08e1613f5ab820983.jpg', '["bitehouse/b954da87a0c043e08e1613f5ab820983.jpg", "bitehouse/4f4f8707a14c4c14a3d30757191a2f76.jpg"]', 133, '合肥', 1332, '瑶海区', '站水万洋科技倒班宿舍', '8号楼3单元30501室', 117.3305090, 31.9174100);
