INSERT INTO "public"."house" VALUES (34010010047, 1, '公寓·京商商贸城(J区) 1室1厅1卫 精装修', 'apartment', 3, 34, '1室1厅1卫', 'one', 'south', 50.00, 1001.00, '房屋隔音效果好，拎包入住，南北通透，朝南户型，室内全天有采光，楼下免费停车，京东方维信诺班车停靠点<br>楼下就是润万家大型商超，小吃街，生活街，大型菜市场，购物生活便捷，足疗按摩洗浴应有尽有<br>交通便利，楼下就是地铁4号线出口，出行便捷', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/1df96a4aeb4f49e2aaef98c241466e98.jpg', '["bitehouse/1df96a4aeb4f49e2aaef98c241466e98.jpg", "bitehouse/188fabb0c47e4b84b7d7d3cd592a958a.jpg"]', 133, '合肥', 1332, '瑶海区', '京商商贸城(J区)', '11号楼1单元10102室', 117.3490830, 31.9286220);
