INSERT INTO "public"."house" VALUES (37010010006, 1, '公寓·华润置地广场商住楼 2室1厅1卫', 'apartment', 14, 27, '2室1厅1卫', 'two', 'south', 51.00, 1799.00, '1.精装修，房间整洁，温馨舒适<br>2.紧邻龙湖天街，省立东院，浪潮，省政府，奥体中心，财富中心，万象城，山东发展，担保大厦，万科中心，山东第一高<br>3.家电齐全配套齐全，床，衣柜，桌子，空调，洗衣机，热水器，洗衣机，油烟机等<br>4.小区绿化高，环境优美，物业管理，居住安心省心，不扰民，安全放心<br>5.周边银座商场，超市，银行，医院诊所，交通便利，生活便捷，', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/3da71fa8707f45aaa66177651ca14db6.jpg', '["bitehouse/3da71fa8707f45aaa66177651ca14db6.jpg", "bitehouse/8d93c0601db148fc8b380d30c228352f.jpg"]', 169, '济南', 1620, '历下区', '华润置地广场商住楼', '4号楼2单元21201室', 117.0980080, 36.6762240);
