INSERT INTO "public"."house" VALUES (37010010032, 1, '公寓·黄台大健康产业智谷 1室1厅1卫 首租', 'apartment', 8, 28, '1室1厅1卫', 'one', 'south', 48.00, 1050.00, '①交通地段枢纽近公交站点<br>②全明户型采光极好生活方便<br>③配置齐全家电家具全新<br>④装修保养好房型设计布局合理适宜居家<br>⑤物业管理好环境优雅绿-化-率-高<br>⑥业主诚心出租因工作便宜出租<br>请给我们彼此一个机会让我为您找到一个舒适的家！<br>温馨提示:租房流失很快，1-2天有效期，来电如果房源已租请不必灰心，我专做租房可提供其他在租的多套房源，只要将您的找房需求告诉我，一定帮您找到合适您的房子！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/d610eb4a78384ea4b5902f48367bfd77.jpg', '["bitehouse/d610eb4a78384ea4b5902f48367bfd77.jpg", "bitehouse/01c38553a3f44cdf92c4f926ad82d6d3.jpg"]', 169, '济南', 1623, '天桥区', '黄台大健康产业智谷', '12号楼2单元20501室', 117.0486430, 36.7040880);
