INSERT INTO "public"."house" VALUES (37010010065, 1, '省心租·汉峪金谷金寓 2室1厅1卫 可短租', 'worry_free_rental', 10, 20, '2室1厅1卫', 'two', 'south', 20.00, 549.00, '1、全明格局<br>2、家私家电齐全，提包入住；<br>二、户型介绍<br>1、格局方正，使用率高达90%<br>2、客厅宽敞舒适、落地阳台让充足的阳光不留余地的闯进来<br>3、厨房宽敞，让您和家人有足够的空间展现私家厨艺<br>4、连接客厅和厨房之间是您和家人享受美味的餐厅，让您热情的招待亲朋好友<br>三、社区介绍<br>1、环境优美，适宜居住，人文素质高，物业管理完善，小区治安好<br>2、小区的容积率小，属于低密度社区，非常适', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a168c1628c894313b6d79d157ad67c5e.jpg', '["bitehouse/a168c1628c894313b6d79d157ad67c5e.jpg", "bitehouse/146f390cd04a454782cf2770ea92b5bf.jpg"]', 169, '济南', 1624, '历城区', '汉峪金谷金寓', '1号楼3单元30702室', 117.1486180, 36.6592940);
