INSERT INTO "public"."house" VALUES (37010010107, 1, '省心租·银丰花园 3室2厅2卫 家具家电齐全', 'worry_free_rental', 4, 22, '3室2厅2卫', 'three', 'south', 149.00, 3450.00, '欢迎您光临我的网上，中住领秀城店置业顾问--朱东霞<br>真诚为您服务，下面为您介绍一下这套房源：<br>【位置坐落】银丰花园，社区成熟，环境棒棒哒，配套完善，生活便利。<br>【户型介绍】经典三室两厅两卫，客厅朝阳南北通透，采光充足，户型布局合理，利用率高。<br>【配套优势】市政集中供暖，文明高素质社区，小区免费停车，可拎包入住。<br>更多，更全，更的房源信息，敬请欢迎致电。<br>欢迎实地预约看房！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/53081049e5a24764a0c6356b647b38c8.jpg', '["bitehouse/53081049e5a24764a0c6356b647b38c8.jpg", "bitehouse/02029f9a346949dd8acbd4594e1cd67f.jpg"]', 169, '济南', 1621, '市中区', '银丰花园', '16号楼3单元30303室', 117.0163660, 36.5999610);
