INSERT INTO "public"."house" VALUES (41010010168, 1, '整租·金科城(一期北院) 3室2厅2卫 精装修', 'whole', 17, 34, '3室2厅2卫', 'three', 'south', 122.00, 2650.00, '房间业主打扫的特别干净，屋子保持的也很好。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/39a76418a9844bc9a5ed91888344a207.jpg', '["bitehouse/39a76418a9844bc9a5ed91888344a207.jpg", "bitehouse/b6af966ed5dc472cb1165e80c3a50aee.jpg"]', 185, '郑州', 1756, '中原区', '金科城(一期北院)', '13号楼3单元30902室', 113.5758800, 34.8040150);
INSERT INTO "public"."house" VALUES (37010010204, 1, '整租·美景秀苑 3室2厅1卫', 'whole', 4, 12, '3室2厅1卫', 'three', 'south', 160.00, 3250.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于市中区玉函小区北路伟东新都商圈。<br>【户型面积】<br>这套160平米的3室2厅1卫房源，拥有南北朝向的明亮采光，还配备了电梯，为您提供舒适便捷的居住体验。<br>【家具家电】<br>出租温馨舒适房屋，配备齐全家具家电，尽享便捷生活。冰箱、洗衣机、热水器等家电一应俱全，沙发、可做饭等家具舒适实用，宽带、油烟机、燃气灶等配套设施完善，让您居住无忧。<br>【房主心态】房主为人和善，诚心出租，寻找爱惜房子，讲卫生的有缘人<br>【周边配套】<br>该小区周边拥有丰富的商业配套，距离银座·奥特莱斯(七里山店)446米，距离鄂尔多斯(银座·奥特莱斯)449米，购物便捷。距离宜佳生鲜超市(伟东新都四区店)58米，距离春燕超市77米，距离东港海洋食品平价超市124米，距离宝益康·团购超市200米，距离平价超市烟草专卖212米，满足日常生活所需。距离七里山1272米，距离山东省警官总医院912米，休闲、医疗设施齐全。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/6240dacdcb824a6089937c7dc08493c1.jpg', '["bitehouse/6240dacdcb824a6089937c7dc08493c1.jpg", "bitehouse/4a454818733b4fa1abe746bdf381ba5d.jpg"]', 169, '济南', 1621, '市中区', '美景秀苑', '2号楼1单元10302室', 117.0090530, 36.6159500);
INSERT INTO "public"."house" VALUES (37010010205, 1, '省心租·大辛庄小区 3室2厅2卫 拎包入住', 'worry_free_rental', 9, 33, '3室2厅2卫', 'three', 'south', 120.00, 2050.00, '一，房子已装修，家具家电齐全，已腾房随时可以入住。<br>二，付款方式可以按正常押一付三，长租优先。<br>三，出门就是站牌，高架口很紧，出行方便<br>四，小区物业费1.3元，地暖，附近配套齐全', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9bfb7303b73244a293fe18a14755933d.jpg', '["bitehouse/9bfb7303b73244a293fe18a14755933d.jpg", "bitehouse/1fcc9594d8a24f008c02cf50e331283e.jpg"]', 169, '济南', 1624, '历城区', '大辛庄小区', '6号楼3单元30402室', 117.1045070, 36.7233130);
INSERT INTO "public"."house" VALUES (37010010206, 1, '整租·华润置地昆仑御 4室2厅2卫', 'whole', 1, 13, '4室2厅2卫', 'four', 'south', 155.00, 6550.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于历下区工业南路,近茂岭二号路，属于CBD商圈。<br>【户型面积】<br>这套155平米的4室2厅2卫房源，拥有南北朝向的明亮空间，还配备了电梯，为您提供舒适便捷的居住体验。<br>【家具家电】<br>出租温馨舒适房源，配备齐全家具家电，尽享便捷生活。冰箱、洗衣机、热水器等家电一应俱全，沙发、可做饭等家具舒适实用，宽带、油烟机、燃气灶等配套设施完善，让您居住无忧。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括圭山公园、济南茂岭山公园、斯巴达公园等公园，满足您休闲娱乐的需求。同时，周边有烟酒茶超市、聚邻超市、众合生鲜超市等超市，满足日常生活所需。距离济南华润万象天地购物中心仅343米，购物便捷。此外，还有济南华圣医院为您提供医疗服务。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/efcdf9730c8a48d1a2217709862a5da1.jpg', '["bitehouse/efcdf9730c8a48d1a2217709862a5da1.jpg", "bitehouse/e74d491e666f40488f5bb4d12d2139bc.jpg"]', 169, '济南', 1620, '历下区', '华润置地昆仑御', '12号楼1单元10103室', 117.0974760, 36.6746030);
INSERT INTO "public"."house" VALUES (37010010207, 1, '公寓·卓越时代广场 1室1厅1卫 随时可看', 'apartment', 16, 20, '1室1厅1卫', 'one', 'east', 38.00, 2450.00, '我们的服务<br>付款方式多样化：押一付一压一付三半年付<br>公区厨房、卫生间、走廊，不定期免费保洁。<br>管家服务:看房选房、签订合同、入住搬家、房间物品非人为损坏无偿维修。<br>水费电费都是正规居民用电用水费用标准，绝无乱收费现象。<br>家具齐全，随时拎包入住、周边环境好。<br>闹中取静（非常静谧的地方），居家环境温馨，生活配套设施完善！<br>交通便利，出小区门口就是公交站牌；', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a77326b34e304d2388cf459afcd1246f.jpg', '["bitehouse/a77326b34e304d2388cf459afcd1246f.jpg", "bitehouse/3cf8761956e743238b5c3ca8c1d1087e.jpg"]', 169, '济南', 1620, '历下区', '卓越时代广场', '12号楼3单元31403室', 117.0860590, 36.6521590);
