INSERT INTO "public"."house" VALUES (37010010215, 1, '省心租·龙湖奥东11号 1室1厅1卫 可短租', 'worry_free_rental', 1, 31, '1室1厅1卫', 'one', 'south', 40.00, 1850.00, '户型：一室一厅一卫，朝阳，采光棒。客厅好用，户型方正，格局好，户型设计合理，没有浪费面积。<br>家具家电齐全，应有尽有，新房首租，拎包入住。汉峪金谷、万科中心、金域中心、浪潮、舜泰广场、龙奥金座、奥体中心、玉兰广场、龙奥大厦、华创观礼中心、龙湖奥东11号，碧桂园凤凰中心，舜奥公园、龙奥天街、大华龙悦大厦、万达广场、丁豪广场、济南国际会展中心、齐鲁软件园、省立医院东院、时代、万科城、人寿大厦、万象城、华福维嘉、七里堡、洪家楼、印象城、奥斯卡、舜奥华府、汉峪新苑、德润天玺、南苑小区、鲁邦奥林逸城、东城逸家、草山岭、北胡小区、三盛国际、华皓英伦联邦、瀚裕华园、涵玉翠岭、凤凰国际、中铁26方', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a2603dae06cd4a45b89c1915161900ba.jpg', '["bitehouse/a2603dae06cd4a45b89c1915161900ba.jpg", "bitehouse/bb0759f9f04447da9b8f743d7416ebd2.jpg"]', 169, '济南', 1620, '历下区', '龙湖奥东11号', '15号楼3单元30102室', 117.1332680, 36.6562100);
