INSERT INTO "public"."house" VALUES (41010010164, 1, '整租·瑞锦小区玉兰苑 2室1厅1卫 可月付', 'whole', 12, 27, '2室1厅1卫', 'two', 'south', 73.00, 1550.00, '温馨提示;免费带你看房.不需要缴纳任何看房费用及房源提供费用..除了房租物业您只需要另交水电燃气费用.<br>整租房，《精装修》《不合租》《地铁口》《实地看房为准》<br>小区环境优美，绿化到位，拎包入住，朝南精装大床房，室内装修温馨精致，给您家的感觉干净整洁交通便利购物方便温馨舒适房子出租较快，地图定位会有误差。但是房子都是附近的,整租一室，两室，都有，平台上为引流客户，房子价位偏低。以房东实际报的价格为准<br>微聊可能回复慢，打电话更好了解，一个温馨的家，从一个电话开始..', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9d0af5d1ea2846b7b46a8e9d1f2f9c62.jpg', '["bitehouse/9d0af5d1ea2846b7b46a8e9d1f2f9c62.jpg", "bitehouse/3499f451156d479bb8a1b161ffda59bc.jpg"]', 185, '郑州', 1758, '管城回族区', '瑞锦小区玉兰苑', '6号楼3单元31203室', 113.7891740, 34.7117220);
