INSERT INTO "public"."house" VALUES (41010010203, 1, '省心租·帝湖花园东王府 3室2厅2卫', 'worry_free_rental', 6, 32, '3室2厅2卫', 'three', 'south', 150.00, 2400.00, '正规户型,整套出租,3室2厅2卫,南朝向,普通装修,普通住宅,电梯房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f4ddc388584b4ae78fb280de1fa707af.jpg', '["bitehouse/f4ddc388584b4ae78fb280de1fa707af.jpg", "bitehouse/8a4a9d5fdaf2444db56fedc5e496562b.jpg"]', 185, '郑州', 1756, '中原区', '帝湖花园东王府', '13号楼1单元10203室', 113.6193340, 34.7183240);
