INSERT INTO "public"."house" VALUES (41010010205, 1, '省心租·升龙玺园 2室2厅1卫 随时可看', 'worry_free_rental', 30, 31, '2室2厅1卫', 'two', 'south', 79.00, 2150.00, '房屋详情<br>1、小区位于玉凤路陇海路交叉口，地铁口，交通方便;<br>2、本房是家电齐全，拎包入住;<br>3、本房装修很好，温馨舒适;<br>4、房东人好，希望找一位有品位、高素质的租客;', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/50c4454d95b54e1c817badf4a25eab6a.jpg', '["bitehouse/50c4454d95b54e1c817badf4a25eab6a.jpg", "bitehouse/ea8583131ce1456d8e25116199757bc0.jpg"]', 185, '郑州', 1759, '金水区', '升龙玺园', '17号楼2单元20602室', 113.7109600, 34.7368180);
