INSERT INTO "public"."house" VALUES (42010010116, 1, '整租·中建福地星城 1室1厅1卫', 'whole', 22, 34, '1室1厅1卫', 'one', 'south', 134.00, 2288.00, '房屋介绍<br>1.房子很干净温馨舒适，特别适合居住，小区环境优美2.家具家电齐全随时可拎包入住3.看房时间随时都可以即刻带您去看房，4.交通条件开车出行也非常的便利周边有多路公交环绕。无论是坐车还是自驾出行都非常方便快捷，<br>5.由于每的需求不同，但只要您与本人沟通，本人一定竭尽全力帮您找到合适的房源，用真诚与专业能力为你提供的服务！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8f74ac135bdf4083b9f55cac37304ae1.jpg', '["bitehouse/8f74ac135bdf4083b9f55cac37304ae1.jpg", "bitehouse/fa9a49d1af914d36abc891eaf0adcd1e.jpg"]', 203, '武汉', 1934, '洪山区', '中建福地星城', '14号楼2单元20203室', 114.3453950, 30.5063460);
