INSERT INTO "public"."house" VALUES (42010010152, 1, '整租·航天双城visa公馆 1室1厅1卫 有地铁', 'whole', 8, 33, '1室1厅1卫', 'one', 'south', 50.00, 2050.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于江岸区解放大道2115号，二七路商圈。<br>【户型面积】<br>50平米舒适南向一居室，带电梯，1室1厅1卫，尽享宜居生活。<br>【家具家电】<br>出租温馨舒适房源，配备冰箱、洗衣机、热水器等家电，宽带、沙发等家具一应俱全，让您尽享便捷生活。厨房设有油烟机、燃气灶，可做饭，满足您的日常需求。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，购物中心名称包括东部购物公园、武汉天地壹方北馆、HORIZON壹方等，到购物中心距离近的是东部购物公园，仅107米。此外，到超市距离在200米以内，包括享受都市慢生活(东部购物公园店)等。百货商场名称C2时尚广场距离仅9米。此外，还有综合医院名称如武汉轻工大学教学医院、汉口医院(二七院区)等，到公园距离近的为二七公园，仅371米。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a80fe1940d37485eb6851a7e936c5ed6.jpg', '["bitehouse/a80fe1940d37485eb6851a7e936c5ed6.jpg", "bitehouse/02b2d291901c4b2c8d05559f7512d449.jpg"]', 203, '武汉', 1928, '江岸区', '航天双城visa公馆', '12号楼1单元10203室', 114.3158230, 30.6220660);
