INSERT INTO "public"."house" VALUES (42010010212, 1, '公寓·汉口城市广场SOHO公寓 1室1厅1卫 精装修', 'apartment', 14, 19, '1室1厅1卫', 'one', 'south', 45.00, 1750.00, '正规户型,整套出租,1室1厅1卫,南朝向,精装修,电梯房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a57e10a33ecc4600a4ef6f147432d390.jpg', '["bitehouse/a57e10a33ecc4600a4ef6f147432d390.jpg", "bitehouse/9e702a77077a4fe38f7b1b7d1fadb59a.jpg"]', 203, '武汉', 1928, '江岸区', '汉口城市广场SOHO公寓', '2号楼2单元21204室', 114.3096320, 30.6528700);
