INSERT INTO "public"."house" VALUES (42010010236, 1, '整租·东湖庭园 3室2厅1卫 有地铁', 'whole', 1, 12, '3室2厅1卫', 'three', 'south', 100.00, 2400.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>所属区域是洪山区，位于中北东路301号，附近是欢乐谷商圈。<br>【户型面积】<br>100平3室2厅1卫，南北朝向，带电梯。<br>【家具家电】<br>出租温馨舒适房，配备冰箱、洗衣机、热水器等家电，宽带、沙发等家具，可做饭、油烟机、燃气灶一应俱全，让您享受便捷生活。<br>【周边配套】<br>金地广场购物中心距离该房源仅1566米，周边有老高生鲜超市(欢乐大道店)等5家超市，距离均在百米之内。周边还有华侨城生态艺术公园等5家公园，武汉东亭医院等4家综合医院，满足生活所需。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/5df429bcd3264fafad59362a54df1fea.jpg', '["bitehouse/5df429bcd3264fafad59362a54df1fea.jpg", "bitehouse/9681b458c5594c16bccb0bbff0e8d833.jpg"]', 203, '武汉', 1934, '洪山区', '东湖庭园', '10号楼2单元20101室', 114.3788260, 30.5904090);
