INSERT INTO "public"."house" VALUES (44010010038, 1, '省心租·夏埔村 1室0厅1卫 有地铁', 'worry_free_rental', 3, 7, '1室0厅1卫', 'one', 'west', 25.00, 900.00, '可以直接找房东房源啦！<br>全广州房源都有，直接搜【广州房东群】<br>.<br>本人房东，全新整栋招租！！<br>精装修电梯公寓，拎包入住，家具家电齐全。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a57a6de21a514895ad9d77e02e6efed6.jpg', '["bitehouse/a57a6de21a514895ad9d77e02e6efed6.jpg", "bitehouse/551932ae9bba4ed79115c19d8b59fb3a.jpg"]', 234, '广州', 2236, '增城区', '夏埔村', '3号楼3单元30102室', 113.5653270, 23.1049870);
