INSERT INTO "public"."house" VALUES (44010010136, 1, '省心租·永兴南街自建房 1室0厅1卫 有地铁', 'worry_free_rental', 5, 8, '1室0厅1卫', 'one', 'south', 23.00, 1009.00, '公寓位置:白云东平<br>另夏良，龙归，同和，京溪，永泰，江夏，嘉禾望岗，二号线三号线均可到达<br>房源描述:<br>品牌家电，全新家私，拎包入住，给您一个满意的家。<br>一:房屋配置:衣柜，沙发，茶几，桌子，电脑桌，椅子一应俱全!<br>配全新热水器。另可根据需求配置全新空调，洗衣机，冰<br>箱，网络宽带鬃:专人管理，给你一个安全负责的生活环境<br>二、周边交通配套便利:附近有大量超市，大商场，生活交<br>通方便!<br>三、公交网络四通，外加离地铁站近，出行不愁!<br>四周没有工厂空气环境好，房子格局好，带独立阳台，厨<br>房，卫', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/33723afab55d4bdc88a1258dcc2003d8.jpg', '["bitehouse/33723afab55d4bdc88a1258dcc2003d8.jpg", "bitehouse/a7d1d8e2e5674a4cb08bb4a10bf5747b.jpg"]', 234, '广州', 2230, '白云区', '永兴南街自建房', '15号楼1单元10502室', 113.3178760, 23.2639430);
INSERT INTO "public"."house" VALUES (44010010137, 1, '公寓·创基广场 1室1厅1卫', 'apartment', 16, 22, '1室1厅1卫', 'one', 'west', 32.00, 1800.00, '位于金沙洲黄岐建设大道，商住两用公寓，<br>靠近地铁口，公交直达地铁，网红聚集地，<br>拥有金沙洲，专用地，优越的和居住环<br>境，楼下就是金铂天地，万达广场，周边有大润发，仆蜂莲花，国昌广<br>场，永旺梦乐城！<br>医院：南海区第六人民医院，南方医院<br>泰成逸园分院，广州中医药大学金沙洲医院！<br>学校：泌<br>冲小学，海北小学，石门中学，沙溪小学，海北中学，石门<br>实验学校，白云中学<br>购物：金沙洲万达广场，国昌广<br>场，红星美凯龙，大润发，<br>三骏综合市场，万益广场！<br>银行：<br>农业银行，<br>工商银行，建设银行，', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/94bcc2c1fbc943a9bb1e4ccdab9106b5.jpg', '["bitehouse/94bcc2c1fbc943a9bb1e4ccdab9106b5.jpg", "bitehouse/5442339c32904cc6affd947df488b3d8.jpg"]', 234, '广州', 2267, '南海区', '创基广场', '18号楼3单元30104室', 113.2097160, 23.1308280);
