INSERT INTO "public"."house" VALUES (44010010322, 1, '省心租·万科欧泊 3室2厅2卫 有地铁', 'worry_free_rental', 29, 39, '3室2厅2卫', 'three', 'south', 94.00, 4850.00, '房源概况<br>1）位置：番禺万博万科欧泊<br>2）面积：95平方，<br>3）户型：3房2厅2卫<br>4）配置：房间里面配有空调，热水器等<br>5）装修：精装修<br>交通情况：<br>1）地铁：七号线地铁南村万博站B出口、地铁就在万达广场1号门前；<br>2）公交：番17、番53、番56、788路、番70、302A、等等、官堂万达站、华南新城站、万达广场总站；<br>周边配套：<br>1）商圈：万博CBD、万达广场、中华美食城、四海一、汉溪长隆、万博城、天河城<br>2）餐饮：中餐、西餐、茶餐厅、面馆、一点点奶茶饮店等各色美味俱全！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/39684c221ae44ab797cb528a4e14d5a1.jpg', '["bitehouse/39684c221ae44ab797cb528a4e14d5a1.jpg", "bitehouse/abdb48d65a754f5abd9b7c6781eda5a3.jpg"]', 234, '广州', 2232, '番禺区', '万科欧泊', '13号楼2单元22403室', 113.3549240, 23.0116590);
