INSERT INTO "public"."house" VALUES (44010010326, 1, '省心租·雅居乐荔尚国际 3室1厅1卫 随时可看', 'worry_free_rental', 16, 17, '3室1厅1卫', 'three', 'south', 107.00, 6250.00, '谢谢你打开我的房源，还有更多房源可以推荐给你对比对比。<br>房源详情：<br>1.交通便利。<br>2.此房格局很宽敞，采光通风俱佳；超舒适，南北房型<br>3.好位置，好楼层，闹中取静小区<br>4.干净，不存在楼上晾晒滴水或落物<br>5.精装修，拎包入住', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/bb4737a0f7bc4972a7142ca3712e38de.jpg', '["bitehouse/bb4737a0f7bc4972a7142ca3712e38de.jpg", "bitehouse/aefcc6b406ed470d86922c815db38fd8.jpg"]', 234, '广州', 2226, '荔湾区', '雅居乐荔尚国际', '4号楼3单元30503室', 113.2440170, 23.1167890);
