INSERT INTO "public"."house" VALUES (44010010339, 1, '整租·珠村上社大街小区 1室1厅1卫', 'whole_rent', 5, 6, '1室1厅1卫', 'one', 'south', 40.00, 930.00, '房子房子环境优美,绿化充足,入住即与精英为邻交通便利,附近的公交：B1路、B2A路、B3路、B4路、B4B路、B5路、B6路、B7路、B15路、B16路、B17路、B18路、B19路、B20路、B27路地铁：4号线黄村站公交：B1路、B2A路、B3路、B4路、B4B路、B5路、B6路、B7路、B15路、B16路、B17路、B18路、B19路、B20路、B27路地铁：4号线黄村站,天河区BRT直达，4号地铁线，5号线地铁有小区房，有公寓房。有合租，有整租。有单间，一房，两房和三房。有精装修有普通装修。都是家私电器齐全，可以拎包入住！光线通风好。大路边不走巷子，安全安静', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/63c1b551245047ff82d5b0c240ef5c7e.jpg', '["bitehouse/63c1b551245047ff82d5b0c240ef5c7e.jpg", "bitehouse/a43dca0eb6154bfdb775ed48c053f208.jpg"]', 234, '广州', 2229, '天河区', '珠村上社大街小区', '5号楼3单元30402室', 113.4196320, 23.1248510);
