INSERT INTO "public"."house" VALUES (44010010341, 1, '整租·龙津东路大院 1室0厅1卫', 'whole_rent', 2, 6, '1室0厅1卫', 'one', 'south', 35.00, 2980.00, '华林寺西门口家电齐全近地铁拎包入住实拍图家电齐全，拎包入住随时都可以看房近地铁<br>【特别注意】房<br>【交通便利】近地铁站，上班不怕迟到路线便利<br>【房屋情况】房子宽敞方正采光好，通风透气，不怕回南天。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/922bb3345d994b62be7dd2b305a213bd.jpg', '["bitehouse/922bb3345d994b62be7dd2b305a213bd.jpg", "bitehouse/dc62598adee14cc19f53cd38b8739f16.jpg"]', 234, '广州', 2226, '荔湾区', '龙津东路大院', '8号楼3单元30102室', 113.2504430, 23.1223990);
