INSERT INTO "public"."house" VALUES (44010010503, 1, '整租·柯木塱塘石一街-二街自建房 1室1厅1卫 可短租', 'whole_rent', 3, 7, '1室1厅1卫', 'one', 'south', 30.00, 1500.00, '房屋亮点邻地铁押二付一经济紧张先押一付一配套齐全精装修南北通透有阳台随时看房<br>出租要求租户稳定作息正常<br>房源描述公寓配置:<br>2、家电:空调、洗衣机、热水器，冰箱<br>4、卫生间都有热水器，洗漱池<br>6、全屋wifi覆盖，游戏看视频都OK', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e612a073f2e6422a9b81ea799d1b4134.jpg', '["bitehouse/e612a073f2e6422a9b81ea799d1b4134.jpg", "bitehouse/230ee85929aa4663aca0210039401d46.jpg"]', 234, '广州', 2229, '天河区', '柯木塱塘石一街-二街自建房', '3号楼1单元10202室', 113.4173150, 23.1935820);
