INSERT INTO "public"."house" VALUES (44010010492, 1, '省心租·富力银禧花园 2室2厅1卫 精装修', 'worry_free_rental', 1, 32, '2室2厅1卫', 'two', 'south', 90.00, 6800.00, '推荐5大理由<br>一：地理位置优越，滨江东路好地段。<br>二：公交地铁方便.尤其是出行方便，上下班方便。<br>三：周围购物方便，节省您的宝贵时间。<br>四：绿化率高，环境优美。宁静和谐，好环境总会给人带来好心情。<br>五：房子干净整洁，温馨舒适，窗明几净，随时等您来看房！！！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c78e3ddb12b5418b92f9f26602a3fe00.jpg', '["bitehouse/c78e3ddb12b5418b92f9f26602a3fe00.jpg", "bitehouse/507c45ab88474dbd8f7dc65a339f4d4b.jpg"]', 234, '广州', 2228, '海珠区', '富力银禧花园', '13号楼3单元30103室', 113.2927950, 23.1008700);
