INSERT INTO "public"."house" VALUES (44010010553, 1, '公寓·保利绿地大都汇 1室1厅1卫 拎包入住', 'apartment', 14, 26, '1室1厅1卫', 'one', 'south', 41.00, 1400.00, '1.此房源位为小区中心地带，安静无噪音，舒适安心，小区环境优美，入住率高。<br>2.小区处于繁华地段，周边地铁公交方便出行，更有各大购物，休闲娱乐场所，购物和生活，都方便。<br>3.客厅出阳台宽敞大方使用率超高，户型方正。<br>4.业主诚心出租，性格随和好交际，可随时看房，欢迎电话联系。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/720e05809264422d92b05ebfe6b70b1c.jpg', '["bitehouse/720e05809264422d92b05ebfe6b70b1c.jpg", "bitehouse/bc111b82cadc4d63a7ca92ab5b17ca0d.jpg"]', 234, '广州', 2234, '南沙区', '保利绿地大都汇', '16号楼3单元30302室', 113.5449570, 22.7957570);
