INSERT INTO "public"."house" VALUES (44010010565, 1, '整租·云山诗意人家 3室2厅2卫 拎包入住', 'whole_rent', 1, 18, '3室2厅2卫', 'three', 'north', 110.00, 5950.00, '社区介绍：00<br>环境优美适宜居住人文素质高物业管理完善，社区环境·<br>好房源优势：··<br>1、房间非常干净，精装修，保养的非常好··<br>2、通风采光好，景观非常舒服··<br>3、房子干净整洁，温馨舒适，安静舒适，就等着您的拎<br>包·<br>入住··<br>4、精装修，随时拎包入住，交通非常方便口口<br>《温馨提示》此房源若还不能满足您的需求，同和&amp;京溪<br>嘉禾望岗黄边等等小区，.贴心的带看服务，根据需求推<br>荐更多性价比高的房子，价格实惠，包您满意！！!<br>0--有意向赶紧致电或者微聊了解详情！··<br>--可预约看房。欢迎约看！00', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/bc24a96b5d8e41f381f0cb1064635527.jpg', '["bitehouse/bc24a96b5d8e41f381f0cb1064635527.jpg", "bitehouse/14c4915ba85e42cab53c3ed4f7b2c894.jpg"]', 234, '广州', 2230, '白云区', '云山诗意人家', '6号楼1单元10103室', 113.2890190, 23.2181960);
