INSERT INTO "public"."house" VALUES (44010010570, 1, '省心租·龙口东路192-198号小区 1室1厅1卫 有地铁', 'worry_free_rental', 4, 10, '1室1厅1卫', 'one', 'south', 40.00, 3450.00, '1、户型正：房子户型方正，布局良好，空间使用率高。<br>2、采光好：朝向好，通风好，采光足，视野好。<br>3、房子好：房大厅大，住起来舒服。<br>4、价格优：房子急租，价格笋。户型好，房子户型方正，通风采光好。让您时刻感受温暖的阳光。<br>5、装修佳：装修格局合理。<br>6、交通利：，离广州龙口东公交站，火车站500米。地铁三号线上盖。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/faaf3d719d93445b89a12628eb69c030.jpg', '["bitehouse/faaf3d719d93445b89a12628eb69c030.jpg", "bitehouse/4e75a495f3d944a2983ae55d5a31f791.jpg"]', 234, '广州', 2229, '天河区', '龙口东路192-198号小区', '4号楼3单元30302室', 113.3406880, 23.1393920);
