INSERT INTO "public"."house" VALUES (44010010630, 1, '省心租·萝峰盈晖花园 2室2厅1卫 有地铁', 'worry_free_rental', 41, 44, '2室2厅1卫', 'two', 'south', 77.00, 2150.00, '1小区环境优美，幽居静谧，绿化率-高，宜居条件很棒。<br>2、小区周边配套齐全，基础设施完善，生活便利，休闲娱乐两不误。<br>3、小区公交车站，交通快捷，体会家门口的速度。<br>4、小区安保严格，24h轮岗值班，安全系数高，居住安全。<br>5、房子格局好，户型方正，使用面积大，空间利用。<br>业主心态<br>【诚信申明】用真诚赢得信赖<br>1.出售：多次业主确认。<br>2.价格：确实是业主底价，杜绝欺骗客户，吃差价。<br>3.房型：与误差细小至小数点。<br>4.户型：本人多次与同事实地勘察。<br>服务介绍<br>1本人从事地产行业多年，有多年的行业经验和社会人脉，保证给到您专业的服务，让您省时省力省心.<br>2本人倾向于维护业主方面，经常发掘大量笋盘，帮客户赚.<br>3本人宗旨：专业+服务+态度+真诚=您的放心满意.', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/449e7a982ff7437eaeabf3bdba25f18c.jpg', '["bitehouse/449e7a982ff7437eaeabf3bdba25f18c.jpg", "bitehouse/019b89bfa4c942ccab7f036901282ffe.jpg"]', 234, '广州', 2231, '黄埔区', '萝峰盈晖花园', '15号楼3单元30204室', 113.5234420, 23.1770030);
