INSERT INTO "public"."house" VALUES (44010010633, 1, '公寓·万科世博汇 1室1厅1卫 拎包入住', 'apartment', 12, 26, '1室1厅1卫', 'one', 'south', 28.00, 2250.00, '房源介绍：<br>l【户型】户型方正，朝向：南，厨房，卫生间。<br>l【采光】前方无遮挡，视野开阔，采光一级棒，通风佳。<br>l【装修】业主自住，装修温馨舒适，隔效果好，有5部到6部进口日立电梯，安全省时省心，上下楼方便。<br>l【家私】房屋配置：热水器,空调,冰箱,洗衣机,衣柜,可做饭,沙发,电视,暖气,，可以拎包入住。<br>小区介绍：<br>l【管理】24小时物业管理，楼上楼下智能视频开锁，全天候监控，安全又舒心。<br>l【环境】小区自带花园，鸟语花香，非常安静，绿化多、空气好、环境优美、空气清新，楼下就是一万方的公园，跑步者的圣地。<br>周边配套：<br>l【配套】周边配套设施成熟，有周边医院：广州市番禺区石壁街社区卫生服务中心,石壁街韦涌社区卫生服务站、大型超市周围商店，各大快递公司进驻，周围有肯德基，星巴克，南北药店，小炒餐厅，理发店，水果店，沙县小吃，五金店，生活方便，员村市场、石东市场，阳光酒店、中西餐厅、步行街等，很适合各类创业者，休闲娱乐的好地方。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7e519853604346279d5451917b9a661b.jpg', '["bitehouse/7e519853604346279d5451917b9a661b.jpg", "bitehouse/491c8865b2bf49b494973f63353d689f.jpg"]', 234, '广州', 2232, '番禺区', '万科世博汇', '13号楼1单元10503室', 113.2784970, 22.9872270);
