INSERT INTO "public"."house" VALUES (44010010643, 1, '整租·萝岗万达广场SOHO公寓 1室0厅1卫 有地铁', 'whole_rent', 8, 27, '1室0厅1卫', 'one', 'east', 52.00, 2600.00, '本人2011年进驻萝岗区科学城从事房地产，主要负责萝岗万达广场以及周边、租售专业代理，以及科学城内所有小区商品屋出租、出售业务，一步一个脚印，诚心对待每个新老客户和业主，贴心的服务，欢迎您的来电！<br>1、萝岗万达广场位于广州萝岗区科学城科丰路，地段位置优越，交通便利，环境优美。52平<br>3、万达精装收楼，格局方正实用、保养新净，随时看房，即签即用。<br>4、中高楼层，共28层，通风采光好，阳光充足，温馨舒适，您值得拥有。<br>5、租价：2500<br>物业管理3.6元/平方，水5.15元/吨，电0.995元/度。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/6ac252cf19554aa6824cc0e828686333.jpg', '["bitehouse/6ac252cf19554aa6824cc0e828686333.jpg", "bitehouse/fc025272871a45f8ab13ee0d1d9569f7.jpg"]', 234, '广州', 2231, '黄埔区', '萝岗万达广场SOHO公寓', '13号楼1单元10402室', 113.4670500, 23.1681890);
