INSERT INTO "public"."house" VALUES (44010010657, 1, '整租·亚运城天峯 3室2厅1卫 拎包入住', 'whole_rent', 16, 57, '3室2厅1卫', 'three', 'north', 89.00, 3150.00, '1、房子楼层适中，通风好、单边位置、采光好<br>2、室内现状出租，随时看房<br>3、地理位置优越，靠近海傍地铁站、亚运城广场，周边配套齐全。有商场、公交站、水果店、银行、医院、学校、超市、菜市场、地铁站等一应俱全，适合居家、度假、退休带娃等各年龄段居住。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/84da914fd1f14fc0b0f72e569d12adfa.jpg', '["bitehouse/84da914fd1f14fc0b0f72e569d12adfa.jpg", "bitehouse/1c9f77838f12470684089ff7fa428ee7.jpg"]', 234, '广州', 2232, '番禺区', '亚运城天峯', '9号楼3单元30704室', 113.4913050, 22.9465600);
