INSERT INTO "public"."house" VALUES (44010010661, 1, '整租·嘉尚国际公寓 1室1厅1卫 拎包入住', 'whole_rent', 3, 31, '1室1厅1卫', 'one', 'south', 49.00, 4250.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于天河区沾益直街89-93号，紧邻林和商圈。<br>【户型面积】<br>49平米舒适朝南一居室，带电梯，独享1室1厅1卫。<br>【家具家电】<br>出租房配备齐全，有冰箱、洗衣机、热水器等生活设施，还有宽带、沙发等舒适家居。厨房设施齐全，可做饭、使用油烟机、燃气灶。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括距离东方宝泰购物广场578米、广州ICC环贸天地672米、JC金田广场740米、中信广场760米和佳兆业广场1198米等购物中心。此外，还有喜迎客超市(林和东路店)、众鲜居生鲜超市、扎布拉·斑马生活超市、以化生鲜店(林和分店)、广州幻珊百货店等超市，满足日常生活所需。同时，还有中山大学附属第六医院(北院区)、广东燕岭医院、嘉禧中医医院等综合医院为健康保驾护航。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e6409a9955aa4fafa8e89b1a4a93cb68.jpg', '["bitehouse/e6409a9955aa4fafa8e89b1a4a93cb68.jpg", "bitehouse/f393518f7b4d4447907caae6267009d6.jpg"]', 234, '广州', 2229, '天河区', '嘉尚国际公寓', '4号楼2单元20102室', 113.3303000, 23.1466050);
