INSERT INTO "public"."house" VALUES (44010010688, 1, '省心租·华南碧桂园翠宏台 2室2厅1卫 随时可看', 'worry_free_rental', 1, 6, '2室2厅1卫', 'two', 'south', 88.00, 4550.00, '华南碧桂园物业介绍<br>地址：翠宏台（人车分流小区）<br>面积：88方+25来方入户花园<br>出租价；4300/月<br>户型：2房2厅1卫<br>装修：开发商交楼保养新净<br>朝向；东南朝向通风对流望小区花园景观<br>楼别：楼梯楼2楼总楼高6楼<br>室内配套；家电齐全带上衣物即可入住<br>如何看楼：随时看房<br>交通路线', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f85b8e4db7384bdd97a923c3eb0614a7.jpg', '["bitehouse/f85b8e4db7384bdd97a923c3eb0614a7.jpg", "bitehouse/e276c96914fb464ba0dc0b6ef56f5868.jpg"]', 234, '广州', 2232, '番禺区', '华南碧桂园翠宏台', '16号楼2单元20104室', 113.3623740, 22.9980620);
