INSERT INTO "public"."house" VALUES (44010010725, 1, '整租·嘉仕花园西区 2室1厅1卫', 'whole_rent', 4, 12, '2室1厅1卫', 'two', 'south', 58.00, 3300.00, '房子本人实地看过，没家私，有空调，电梯的小两房，价格便宜。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/4fa54adc47d3402e91dd6f7cf26d5af1.jpg', '["bitehouse/4fa54adc47d3402e91dd6f7cf26d5af1.jpg", "bitehouse/9b3291235c1541b29f21e9e6658719cb.jpg"]', 234, '广州', 2228, '海珠区', '嘉仕花园西区', '3号楼2单元20103室', 113.2927510, 23.1003020);
