INSERT INTO "public"."house" VALUES (44010010778, 1, '省心租·中海金沙湾 2室2厅1卫 拎包入住', 'worry_free_rental', 9, 33, '2室2厅1卫', 'two', 'south', 85.00, 2950.00, '房源描述房源描述房源描述<br>房屋情况介绍：<br>1：业主诚意出租此房，看房方便。<br>2：交通方便，周边公交：公交车：金沙洲总站、金沙洲路站、中海金沙湾总站，途经线路包括205路、283路、夜54路、42路、424路、429路、429A路、885路。看中海金沙湾至广州核心城区的交通四通八达，目前可经金沙洲大桥直通广州市内环路，也可向南通过珠江大桥连通内环路，还可经环城高速浔峰洲出入口快速至广州各区，未来还可以经地块旁规划中的大坦沙大桥，跨过大坦沙岛，直通内环路，交通非常方便。，附近地铁：暂无资料，为您的出行多一份保障，节省您宝贵的时间。<br>3：便利的购物场所是您生活的保障，周围商店：好又多超市、宏城超市、百佳超市、嘉和超市、卜峰莲花，周边银行：农业银行、工商银行、中国银行、招商银行、建设银行。<br>特别提醒：<br>如果此房您不满意，请与我联系，我会根据您的需求，当前市场价位，;给您推荐合适的社区，合适的房子。<br>顺祝您身体健康、工作顺利！！！<br>房源描述房源描述房源描述<br>房屋情况介绍：<br>1：业主诚意出租此房，看房方便。<br>2：交通方便，周边公交：公交车：金沙洲总站、金沙洲路站、中海金沙湾总站，途经线路包括205路、283路、夜54路、42路、424路、429路、429A路、885路。看中海金沙湾至广州核心城区的交通四通八达，目前可经金沙洲大桥直通广州市内环路，也可向南通过珠江大桥连通内环路，还可经环城高速浔峰洲出入口快速至广州各区，未来还可以经地块旁规划中的大坦沙大桥，跨过大坦沙岛，直通内环路，交通非常方便。，附近地铁：暂无资料，为您的出行多一份保障，节省您宝贵的时间。<br>3：便利的购物场所是您生活的保障，周围商店：好又多超市、宏城超市、百佳超市、嘉和超市、卜峰莲花，周边银行：农业银行、工商银行、中国银行、招商银行、建设银行。<br>特别提醒：<br>如果此房您不满意，请与我联系，我会根据您的需求，当前市场价位，;给您推荐合适的社区，合适的房子。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7b3be4db55f04ce2b147706077807c58.jpg', '["bitehouse/7b3be4db55f04ce2b147706077807c58.jpg", "bitehouse/1360b2ba60ca40a987804d1b4131d9f1.jpg"]', 234, '广州', 2267, '南海区', '中海金沙湾', '4号楼3单元30101室', 113.2067660, 23.1390010);
