INSERT INTO "public"."house" VALUES (44030010055, 1, '公寓·南联马岭新工业区 1室0厅1卫 有地铁', 'apartment', 1, 4, '1室0厅1卫', 'one', 'south', 28.00, 1030.00, '房间位置优势:<br>门口，南联第五工业区公交站台，近龙城广场地铁站，南联地铁站一公里内，爱南路227号。<br>房间商圈优势:<br>近体育场，龙城广场，万科广场，南联商圈，美食街，正中高尔夫球场，酒店，养生…<br>房间安全:<br>专职管理人员全天维护服务，全天保安三班轮岗，电子门锁，门禁卡出入，联网警务室监控。<br>房间卫生:<br>一客一消毒，房间清退时全面消毒液喷洒，保洁全天打扫。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/6400362f2e54489bab04330e0e3c5af9.jpg', '["bitehouse/6400362f2e54489bab04330e0e3c5af9.jpg", "bitehouse/8a4a9d5fdaf2444db56fedc5e496562b.jpg"]', 236, '深圳', 2251, '龙岗区', '南联马岭新工业区', '11号楼2单元20101室', 114.2590120, 22.7071770);
