INSERT INTO "public"."house" VALUES (44030010082, 1, '整租·五和新村 1室0厅1卫 有地铁', 'whole_rent', 9, 12, '1室0厅1卫', 'one', 'south', 30.00, 2230.00, '房屋介绍<br>精装公寓单间一房两房出租<br>配热水器、空调、油烟机、床、衣柜，带阳台，独立厨卫，电梯房，可养宠物。大小单间，一房两房。<br>1．周边配置成熟2．配全新品牌私电器，专人管理，豪华高端的装修风<br>3．有阳台，有厨房，独立卫生间，通风采光，私电器都是从国美团购过来的<br>4、白领人适居，居住条件好，住非常安全温馨<br>5．户型多样现有单、一房不同户型不同价位<br>6．公寓房间配置床、衣柜、桌子、小茶几、空调、热水器、油烟机、冰箱、洗衣机', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7d4fee4943e0426f9efc745277a8b033.jpg', '["bitehouse/7d4fee4943e0426f9efc745277a8b033.jpg", "bitehouse/a6f0f14f0912462ab36511c0473d8aeb.jpg"]', 236, '深圳', 2251, '龙岗区', '五和新村', '10号楼1单元10104室', 114.0604730, 22.6209720);
