INSERT INTO "public"."house" VALUES (44030010135, 1, '省心租·万丰村 1室0厅1卫 拎包入住', 'worry_free_rental', 1, 2, '1室0厅1卫', 'one', 'south', 30.00, 800.00, '1：精装装修，全新家私家电，去地铁口很方便、<br>2：采光好，通风好东南朝向，宽敞明亮通风温馨，楼下超大免费停车场。<br>3：现有房源为户型多样的，全新设计地中海风格，选材低碳环保，高档配套设施齐全，随时拎包即可入住。<br>4：房间阳光充足，格局方正，有独立卫生间、厨房、；全新家私家电：空调、热水器，洗衣机，冰箱，衣柜，沙发，电脑桌，床。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9aac2b37e02b420885b9d59a2d4107a3.jpg', '["bitehouse/9aac2b37e02b420885b9d59a2d4107a3.jpg", "bitehouse/40d3ab19c669473ca95ec99501eebfb7.jpg"]', 236, '深圳', 2250, '宝安区', '万丰村', '17号楼1单元10103室', 113.8251800, 22.7241040);
