INSERT INTO "public"."house" VALUES (44030010183, 1, '省心租·沙元埔村 2室1厅1卫 精装修', 'worry_free_rental', 8, 12, '2室1厅1卫', 'two', 'south', 60.00, 2550.00, '请直接拨打电话，自己房子。不收任何费用！<br>有单间，复试，一房一厅，两房一厅<br>1.采光超好，房子新装修，所有设备都是全新配置，包含超大阳台，光线通风都非常好，晾衣服方便。<br>2.家电配置齐全（空调，热水器，衣柜，床，沙发，茶几，宽带，洗衣机，独立卫生间，独立水电表）<br>3.专人管理安全舒适，智能门锁，温馨单间，情侣套间<br>4.购物消费更是方便，娱乐场所等', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c0773b2066d942a4a413da56211467f3.jpg', '["bitehouse/c0773b2066d942a4a413da56211467f3.jpg", "bitehouse/f771c854a9c64615b05d829f53c90a65.jpg"]', 236, '深圳', 2253, '龙华区', '沙元埔村', '7号楼1单元10402室', 114.0410780, 22.6195160);
