INSERT INTO "public"."house" VALUES (44030010189, 1, '省心租·辉豪工业园 1室0厅1卫 有地铁', 'worry_free_rental', 1, 12, '1室0厅1卫', 'one', 'south', 25.00, 880.00, '1：本公寓家私家电配齐，拎包入住。<br>2：公寓房间宽敞，晾晒方便。阳光和通风都相当的好<br>3：全新装修的房子，全新的家私家电，房东出租，拎包入住。<br>4：安全方面：我们公寓每层楼层都会有*系统、大门有门禁、进出都要刷卡、24*运行，专人管理，保证安全！<br>5：周边超市，银行，商场，酒店，饭店等设施一应俱全。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/849a95003e284c868e0b76207966612f.jpg', '["bitehouse/849a95003e284c868e0b76207966612f.jpg", "bitehouse/13047a4596d944b1b20c5d10a4635bfb.jpg"]', 236, '深圳', 2255, '光明区', '辉豪工业园', '14号楼1单元10104室', 113.8872910, 22.7718030);
