INSERT INTO "public"."house" VALUES (44030010238, 1, '整租·汇邦名都花园(二期) 2室2厅1卫 随时可看', 'whole_rent', 18, 22, '2室2厅1卫', 'two', 'south', 68.00, 4400.00, '汇邦名都花园是一个集人才住房、公寓、商务、大型时尚shoppingmall于一体的都会综合体。其中还规划有多区庭院式下沉休闲广场，并配备有4800㎡的。<br>汇邦名都花园商业MALL采用环岛型连廊&amp;amp;rdquo;设计，多首层&amp;amp;rdquo;建筑结构与四大地下通道和龙骨架时光道连廊的多维度立体商业结构，将三大街区有机循环的串联起来<br>小区内部配套；约7.2万平方米的商业配套，海底捞等企业入驻<br>周边设施<br>交通公交：B780路、专59路、专91路、专61路、B890路、B692路；<br>地铁：6号线(在建中)、13号线（规划中）<br>：洋洋春天、龙田，翔翎凤，园育', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/76c47ee5f8bb466084e7e483a91b4d58.jpg', '["bitehouse/76c47ee5f8bb466084e7e483a91b4d58.jpg", "bitehouse/a0ebea7d039044b49d7fa880b0960582.jpg"]', 236, '深圳', 2250, '宝安区', '汇邦名都花园(二期)', '15号楼1单元11801室', 113.9715310, 22.6921930);
