INSERT INTO "public"."house" VALUES (44030010240, 1, '整租·甲子塘村 1室0厅1卫', 'whole_rent', 4, 7, '1室0厅1卫', 'one', 'south', 25.00, 980.00, '非中介，零费用。本套房屋介绍：1:地理位置：本套房屋毗邻地铁6号线长圳，交通出勤方便，出门便是地铁站，公交站；2:周边配套：购物广场，市场就在旁边，衣食娱乐，近在咫尺；大型综合菜市场，从蔬菜到肉类，蛋类，茶米油盐酱醋茶一应俱全；3:户型配置：电梯房，该套房屋坐北朝南，格局方正，独立阳台，独立卫生间，干湿分离，采光通风非常好，家私家电全配齐，拎包入住。本司为品牌连锁公寓企业，旗下拥有大量物业，遍布整个公明镇；完善的租后服务，屋美价廉的租金，透明的水电杂费，真实的租金价格，真实的房屋广告图片；户型涵盖单间、一房一厅、两房、三房、四房、独户独院，欢迎，微信同号！！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/d885f94e23714527a2cfe497f7eb546e.jpg', '["bitehouse/d885f94e23714527a2cfe497f7eb546e.jpg", "bitehouse/d418bef677a44afd8758f61e7b587ae7.jpg"]', 236, '深圳', 2255, '光明区', '甲子塘村', '6号楼1单元10402室', 113.9194200, 22.7314050);
