INSERT INTO "public"."house" VALUES (44030010244, 1, '整租·合正汇一城 2室1厅1卫', 'whole_rent', 4, 31, '2室1厅1卫', 'two', 'south', 73.00, 7050.00, '业主自住朝东南<br>楼下天虹正地铁口<br>生活方便随时看房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/00b76f64401e4fd79ab02e7d9e0f222c.jpg', '["bitehouse/00b76f64401e4fd79ab02e7d9e0f222c.jpg", "bitehouse/c0447c022dd74f68969f8f403655fd44.jpg"]', 236, '深圳', 2250, '宝安区', '合正汇一城', '5号楼2单元20404室', 113.8642670, 22.5755700);
