INSERT INTO "public"."house" VALUES (44030010308, 1, '整租·会展湾水岸广场 1室1厅1卫 有地铁', 'whole_rent', 3, 25, '1室1厅1卫', 'one', 'east', 37.00, 2850.00, '【交通便捷】<br>邻近地铁20号线国展南站，地铁直通机场北、可转线罗湖，福田商务圈；到前海、科技园、宝安中心等上班便利；<br>【房间配置】<br>户型结构宽敞！通风采光！舒适方正！厨房、洗手间，全新精装修，<br>【家私家电】<br>室内全新配置：床、床垫、衣柜、桌椅、窗帘、卫浴、冷暖空调、洗衣机、冰箱、中央热水器；<br>【周边设施】<br>同泰时代广场、益田日天地、LeSuper超市、中l国际影城、深圳国际会展中心<br>【品质小区】', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7acdd38ce00b41a2899e3a45a22817df.jpg', '["bitehouse/7acdd38ce00b41a2899e3a45a22817df.jpg", "bitehouse/88b6456ea8d0447b8f8f9ae1c05f61b7.jpg"]', 236, '深圳', 2250, '宝安区', '会展湾水岸广场', '9号楼3单元30204室', 113.7810460, 22.7011650);
