INSERT INTO "public"."house" VALUES (44030010314, 1, '整租·东边老村 1室1厅1卫 有地铁', 'whole_rent', 3, 7, '1室1厅1卫', 'one', 'south', 46.00, 2480.00, '1、户型：方正户型，单间宽4米长6米，一房一厅宽6米长8米，独立卫生间，独立厨房。<br>2、采光：南北通透，采光非常好。<br>3、配套：电梯床衣柜梳妆台沙发茶几空调热水器冰箱洗衣机抽油烟机等。<br>4、物管：带电梯，门禁刷卡，管理人员值守，公共区域每日保洁。<br>5、配套完善，交通非常便利，步行到民治地铁口。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9c8309169dd644698544dcc0793e6812.jpg', '["bitehouse/9c8309169dd644698544dcc0793e6812.jpg", "bitehouse/853d1c915427499297d47606b807a929.jpg"]', 236, '深圳', 2253, '龙华区', '东边老村', '12号楼1单元10301室', 114.0383250, 22.6230750);
