INSERT INTO "public"."house" VALUES (44030010316, 1, '整租·蚝业雅苑 2室2厅1卫 有地铁', 'whole_rent', 11, 28, '2室2厅1卫', 'two', 'south', 65.00, 5050.00, '蚝业雅苑位于西乡地铁口A/B出口200m左右，电梯小区房，天虹旁边，配套齐全。<br>电梯标准两房，客厅出阳台视野无遮挡，通风采光好，明厨明卫，部分家私家电，带空调热水器油烟机炉灶。<br>小区收费标准：水4.2元/立方左右（含污水处理费和垃圾处理费），电0.78元/度（无梯度），天燃气3.4元/立方，物业费2.5元/平。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/13b22b7c0c564fd8bb135a1f73eb4439.jpg', '["bitehouse/13b22b7c0c564fd8bb135a1f73eb4439.jpg", "bitehouse/fcdcdcc4a2324cf1bff5d5e0f83bf96f.jpg"]', 236, '深圳', 2250, '宝安区', '蚝业雅苑', '13号楼1单元10104室', 113.8638220, 22.5770550);
