INSERT INTO "public"."house" VALUES (44030010607, 1, '个人房源·八卦岭宿舍 1室0厅1卫 有地铁', 'personal_house', 2, 7, '1室0厅1卫', 'one', 'south', 25.00, 2650.00, '没有中介费整租大小单间全新家具家电<br>一、本公寓可随时拎包入住。专人管理，楼层干净卫生<br>生活便利：附近有超市、杂货店、饭店、银行、宾馆、药房和诊所方圆百米内都有<br>二、本公寓配置有：空调、热水器、席梦思床、衣柜、梳妆台宽带、独立的厨房卫生间。<br>公寓地理位置好多条公交线路：步行很快就到地铁站和公交站，多条公交线路方便出行。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/11262d89d5644ccdabf578d1771e76e0.jpg', '["bitehouse/11262d89d5644ccdabf578d1771e76e0.jpg", "bitehouse/90804d8f5e924811b39d14dc2cc85328.jpg"]', 236, '深圳', 2248, '福田区', '八卦岭宿舍', '19号楼1单元10204室', 114.1029230, 22.5595000);
