INSERT INTO "public"."house" VALUES (44030010631, 1, '省心租·丽园小筑 2室1厅1卫 拎包入住', 'worry_free_rental', 12, 20, '2室1厅1卫', 'two', 'south', 68.00, 2700.00, '一、房源优势<br>1、格局方正，每天都可享受清晨的第一缕阳光。<br>2、家私家电齐全，直接拎包入住。<br>二、房屋介绍<br>1、客厅.宽敞.大方.使用率高。<br>2、卧室温馨舒适.搭配心怡。<br>3、厨房设施齐全.让美味来的更加轻松。<br>三、社区配套<br>1、环境优雅，空气清新，低密度社区。<br>2、小区绿化率高，让您感受像花园一样的家<br>3、购物：茂胜佳超市，天虹商场，沃尔玛商场<br>4、学校：松岗中学、松岗中英文学校、<br>5、医院：松岗医院<br>6、银行：中国银行，建设银行，交通银行，农业银行，工商银行，农村商业银行等', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9c2d03faf24043e8812f9e18eb59e0d2.jpg', '["bitehouse/9c2d03faf24043e8812f9e18eb59e0d2.jpg", "bitehouse/11bc4628a1be4e128fb1384a7a501424.jpg"]', 236, '深圳', 2250, '宝安区', '丽园小筑', '8号楼2单元20704室', 113.8508600, 22.7671020);
