INSERT INTO "public"."house" VALUES (44030010720, 1, '整租·上辇新村 1室0厅1卫 有地铁', 'whole_rent', 2, 7, '1室0厅1卫', 'one', 'south', 35.00, 1150.00, '本套房屋介绍：<br>1:地理位置：本套房近地铁站、商超、通风朝阳光线好、距离中小学很近，交通出勤方便，出门便是公交站。<br>2:周边配套：大型商场就在旁边，衣食娱乐，近在咫尺；大型综合菜市场步行100米，从蔬菜到肉类，蛋类，米、油、盐、酱、醋、茶、一应俱全。<br>3:户型配置：电梯房，该套房屋坐北朝南，格局方正，面积有约60+平方，独立卫生间，干湿分离，采光通风非常好，家私家电全配齐，拎包入住。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/07f6fa3dedae409ab412c768fc494b73.jpg', '["bitehouse/07f6fa3dedae409ab412c768fc494b73.jpg", "bitehouse/590e273e84dc419a860047f98499f204.jpg"]', 236, '深圳', 2255, '光明区', '上辇新村', '14号楼3单元30101室', 113.9052820, 22.7840380);
