INSERT INTO "public"."house" VALUES (45010010178, 1, '省心租·桃花源祈福城 3室2厅1卫', 'worry_free_rental', 4, 6, '3室2厅1卫', 'three', 'south', 94.00, 1650.00, '精装时尚风格，家电齐全，拎包入住。<br>服务包含:公共区每周双保洁，定期有专人上门进行安全排<br>查，避免各种安全隐患。<br>房间配置:双人床，双门衣柜，书桌，椅子，床头柜，等.….<br>二、周边配套<br>1优越的地理位置，交通购物方便<br>2.周边设施完善，绿化广泛<br>3房间真实有效，随时看房<br>此地段附近还有很多这样的房源，房子属于交通便利，出门', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ee5576e764d745e8b43620c1e0a6211e.jpg', '["bitehouse/ee5576e764d745e8b43620c1e0a6211e.jpg", "bitehouse/7fa2703f1755409e952e38aa99cc3848.jpg"]', 255, '南宁', 2353, '西乡塘区', '桃花源祈福城', '3号楼3单元30204室', 108.3077520, 22.8755700);
