INSERT INTO "public"."house" VALUES (45010010241, 1, '个人房源·黄屋坡自建房 1室0厅1卫 可短租', 'personal_house', 1, 8, '1室0厅1卫', 'one', 'south', 25.00, 750.00, '房型价格（看房免费）所有房源均为实拍~<br>1、单间配套：400-1100/月（多套不同价位可看可选）<br>2、一房一厅：1200-1300-1400/月（多套不同价位可看可选）<br>公寓配套<br>1、每套房都是独立卫生间，独立厨房（厨台），独立水表，独立电表。<br>2、固定配有：床，衣柜，热水器，电脑桌，电脑凳，油烟机，WiFi<br>3、可加配：冰箱，洗衣机，空调<br>本人服务小区有：新竹小区、鲤湾路、检察院、竹苑小区、公安厅、华龙苑、兴达苑、振华苑、方圆小区、建院、电视台宿舍、农垦局宿舍、园湖路，自治区委员会厅印刷厂，怡和信苑', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/162f5eaee3724443a6a1bde0e71bbee4.jpg', '["bitehouse/162f5eaee3724443a6a1bde0e71bbee4.jpg", "bitehouse/7b094dea42424e389bd268671e34d5db.jpg"]', 255, '南宁', 2351, '青秀区', '黄屋坡自建房', '5号楼2单元20102室', 108.3455460, 22.7981640);
