INSERT INTO "public"."house" VALUES (45010010256, 1, '个人房源·恒大苹果园 1室1厅1卫', 'personal_house', 9, 99, '1室1厅1卫', 'one', 'south', 60.00, 1800.00, '无中介押一付一可转租不扣押金<br>南宁有1000+套房源每个区域都有工作变动随意换房<br>一、房屋描述<br>精美装修风格，家电齐全，拎包入住<br>服务包含:公共区每月有保洁阿姨2-3次清洁，定期专人进行安全排查，避免各种安全隐患<br>房间配置:床，双门书柜，书桌，椅子，床头柜，等<br>二、周边配套<br>1.优越的地理位置，交通购物方便，周边设施完善，绿化广泛<br>2.房间真实有效，随时看房<br>此地段附近还有很多这样的房源，房子属于，交通便利:地铁，公交公共交通便捷无忧，出门不远就是地铁口，小区门口24小时安保，给您一个安全舒适的环境<br>3.房子500-1300都有，房租每个月付智能门锁，密码', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/1286d87a7cd64b26a907caa132de87e3.jpg', '["bitehouse/1286d87a7cd64b26a907caa132de87e3.jpg", "bitehouse/ca626cd4d98d4e359d0a0e453832e841.jpg"]', 255, '南宁', 2351, '青秀区', '恒大苹果园', '3号楼1单元10903室', 108.4229050, 22.8000840);
