INSERT INTO "public"."house" VALUES (46010010059, 1, '省心租·天地凤凰城 2室2厅1卫 可短租', 'worry_free_rental', 23, 25, '2室2厅1卫', 'two', 'south', 72.00, 2000.00, '房屋托管找我（可空房托管/配齐托管）.本房源可短租~2房1卫~采光好~家具家电齐全~拎包入住.租房找我!一切都可以谈!本人只做海口西海岸租房~几百套1-4房出租~总有一款适合您!', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/aa46a8f0f13144268bfd86788a05ded6.jpg', '["bitehouse/aa46a8f0f13144268bfd86788a05ded6.jpg", "bitehouse/57206eab0f3b40dc84d65c10dfdbf125.jpg"]', 269, '海口', 2461, '秀英区', '天地凤凰城', '15号楼2单元21403室', 110.1921930, 20.0522510);
