INSERT INTO "public"."house" VALUES (46010010075, 1, '省心租·伊泰天骄(一期) 2室2厅1卫', 'worry_free_rental', 4, 18, '2室2厅1卫', 'two', 'south', 60.00, 1850.00, '1,小区位于繁华地段，小区环境优美，适宜居住，物业管理完善，交通便利，<br>2，周边配套齐全，五源河农贸市场，五源河学校，肿瘤医院，大型商超远大星茂海口免税城，假日沙滩，周围有各大银行供使用，,娱乐设施，健身设施结为一体，样样齐全，<br>3，楼层，精装修，户型方正,，南北通透，采光通风通风良好，冬暖夏凉，<br>4，图片均为本人实地拍摄，欢迎随时看房', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/5169ab64aaae4d0ebfaa20a9890f68c3.jpg', '["bitehouse/5169ab64aaae4d0ebfaa20a9890f68c3.jpg", "bitehouse/828336e7bb514ba790adb9ded45c4549.jpg"]', 269, '海口', 2461, '秀英区', '伊泰天骄(一期)', '4号楼3单元30302室', 110.1837220, 20.0456250);
