INSERT INTO "public"."house" VALUES (46010010099, 1, '省心租·晨晖玺樾 2室1厅1卫', 'worry_free_rental', 12, 23, '2室1厅1卫', 'two', 'south', 72.00, 2400.00, '房源亮点：该小区地理位置优越，交通方便，附近有超市商场等，房子视野开阔，通风效果好，生活方便，基本生活需求都能满足。<br>户型简介：该房子户型方正，通风、采光效果好，视野宽阔。<br>装修描述：该房子属于精致装修，房内的采光充足，通风透气，很适宜居住。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/98cbc4e52ec248618b494ad7b3e0ccbc.jpg', '["bitehouse/98cbc4e52ec248618b494ad7b3e0ccbc.jpg", "bitehouse/26fedb89feae4f56bdfa3755d30e6bdd.jpg"]', 269, '海口', 2461, '秀英区', '晨晖玺樾', '10号楼1单元11003室', 110.1862790, 20.0540500);
