INSERT INTO "public"."house" VALUES (46010010182, 1, '整租·华昌大厦 1室1厅1卫 拎包入住', 'whole', 14, 17, '1室1厅1卫', 'one', 'south', 45.00, 1800.00, '您好，我是乐安居小林本人发表的房屋图片都是实拍，房源价格均为房东实际价格，可以提高价格小区配套齐全周边有酒吧、学校、医院、超市。公交车站、交通便利。房子采光极好，家电家具齐全，拎包入住，南北通透夏天开窗可不开空调都很凉快，周边生活配套齐全，接送小孩上学或上班都交通便利，欢迎电话看房。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/33d48e6cbffb4778ab2fd2b0900b3db0.jpg', '["bitehouse/33d48e6cbffb4778ab2fd2b0900b3db0.jpg", "bitehouse/ff74b7bd38dd49f98e2d43eeafda1ab2.jpg"]', 269, '海口', 2462, '龙华区', '华昌大厦', '13号楼1单元11102室', 110.3167530, 20.0237710);
