INSERT INTO "public"."house" VALUES (50000010029, 1, '省心租·东和银都 1室0厅1卫 随时可看', 'worry_free_rental', 11, 32, '1室0厅1卫', 'one', 'south', 43.00, 2149.00, '为年轻人打造理想租房生活<br>全国品牌连锁公寓，知名设计师匠心打造美式田园风、欧式简约风、优雅地中海等装修风格，全新家具电器，手绘油画装点你的梦想空间。众乾信给予您的不仅仅是租住忧，更是高品质的生活体验。<br>房源特点：<br>一房屋优势1、朝向日照充足2、室内装修简洁大方、拎包入住<br>二房屋介绍1、客厅宽敞大方使用率高2、卧室温馨舒适3、厨房设施<br>三社区配套1、环境优雅、低密度社区2、小区绿化率高空气清新房租可月付可季度付入住深度保洁１客１锁专属管家免上门维修<br>房源描述周边配套设施：', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/60646cc4274c46c8b60de674a88cd3b7.jpg', '["bitehouse/60646cc4274c46c8b60de674a88cd3b7.jpg", "bitehouse/828336e7bb514ba790adb9ded45c4549.jpg"]', 288, '重庆', 2636, '江北', '东和银都', '19号楼3单元30702室', 106.5260520, 29.5839610);
