INSERT INTO "public"."house" VALUES (50000010046, 1, '公寓·旭辉城(商住楼) 1室1厅1卫 拎包入住', 'apartment', 4, 17, '1室1厅1卫', 'one', 'south', 29.00, 899.00, '社区环境1.周边交通便利：紧邻城市主干道享受地铁、数十余公交线路等便利的交通设施2.专业打造一个纯居住的小区，绿化率高，社区环境好推荐理由1.经典户型，客厅卧室全带阳台飘窗，明厨明卫，居住非常舒适，利用率超高！2.业主自住的#装修#，家具家电俱全！3.租价合理，非常超值，业主诚意出租，看房随时！欢迎您点击我的头像进入我的，有更多超值户型等您选择，期待您的！！另：本人郑重将为您的电话号码提供保密，以免让您接到不必要的打扰电话！！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7d9f8c408ddf4372867b4c1a5e5893fb.jpg', '["bitehouse/7d9f8c408ddf4372867b4c1a5e5893fb.jpg", "bitehouse/d92d195eae454caba34b4cf31e155b49.jpg"]', 288, '重庆', 2644, '巴南', '旭辉城(商住楼)', '18号楼3单元30401室', 106.5443830, 29.4015420);
INSERT INTO "public"."house" VALUES (50000010047, 1, '省心租·渝能都市经典 3室2厅1卫 拎包入住', 'worry_free_rental', 6, 30, '3室2厅1卫', 'three', 'south', 8.00, 550.00, '联系我随时看房！<br>1.！（水电气透明可查,没有任何附加用的哇）<br>2.一客一锁（安全又方便）麻麻再也不怕我钥匙丢了<br>3.提供WiFi(妹子，连了我家WiFi，就是我家的人了)<br>4.及时维修（虽然不是你男朋友，但我们能随叫随到帮你换灯泡）<br>5.提供保洁（每周一次保洁,给你一个舒适的居住环境）<br>6，看上的房子价格可以谈，房源非常多，只有你想不到，没有我找不到的房源，包给你找到满意的为止！！！', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e6160249f6984816ab5638c2609925c3.jpg', '["bitehouse/e6160249f6984816ab5638c2609925c3.jpg", "bitehouse/7fcba5c5d297421ebb26aceb9388218c.jpg"]', 288, '重庆', 2639, '南岸', '渝能都市经典', '20号楼2单元20504室', 106.5714720, 29.5201860);
