INSERT INTO "public"."house" VALUES (50000010056, 1, '整租·康德国会山 2室1厅1卫 拎包入住', 'whole', 28, 30, '2室1厅1卫', 'two', 'south', 61.00, 1950.00, '房屋介绍<br>我们承诺:1、不予虚假房源吸引客户!2、不予虚构价格招揽客户!3、我们的服务绝不打折!由于近期成交量活跃，部分房源已租或价格有调整，所以本人已发布房源可能会和网站上其他同行价位有相差性，但可以保证本人所发一切房源均为、价格和真实图片，议价是本人的强项!如果您对此房源还不满意，请点击我的头像，进入我的，或拨打咨<br>询电话。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a418fe6b605042ea8e91f6c9e0bc9edd.jpg', '["bitehouse/a418fe6b605042ea8e91f6c9e0bc9edd.jpg", "bitehouse/73c3dc3a803b42fbb02229def1a011fd.jpg"]', 288, '重庆', 2639, '南岸', '康德国会山', '14号楼1单元11504室', 106.5783280, 29.5273270);
INSERT INTO "public"."house" VALUES (50000010057, 1, '公寓·万寿福居D区25栋 2室1厅1卫 可短租', 'apartment', 2, 26, '2室1厅1卫', 'two', 'south', 69.00, 1050.00, '冠寓属于龙湖集团旗下的长租公寓品牌，为追求生活品质的年轻人打造宜居生态圈，国内长租公寓TOP1品牌<br>【租房必看】独栋公寓，精装全配拎包入住，<br>【促销优惠】邀请好友入住，立减200元<br>【租期付款】租金可月付/季付，一个月起租<br>【公寓安全管理】小区安保、实名登记、消防设备设齐全<br>【社区活动】公寓定期与租客共同举办节日活动，平日组织狼人杀、网络游戏等小型活动<br>【门店地址】重庆市北碚区万寿福居D区25幢<br>【精装套房|拎包入住|独立卫浴|高速WIFI】【共享公区|休闲娱乐】200㎡公区超大小区环境|对冠寓住户开放：健身房、会客区、影音区、桌球台等', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8913829aef7d4d05b25c04edc1810f28.jpg', '["bitehouse/8913829aef7d4d05b25c04edc1810f28.jpg", "bitehouse/7be032e3aed44cb9bef8401c20e12a98.jpg"]', 288, '重庆', 2640, '北碚', '万寿福居D区25栋', '14号楼1单元10104室', 106.5302540, 29.8220860);
