INSERT INTO "public"."house" VALUES (50000010116, 1, '整租·秀丽景苑 2室2厅1卫', 'whole', 6, 7, '2室2厅1卫', 'two', 'south', 73.00, 1150.00, '您好：尊敬的客户，欢迎光临小冉的………..<br>请您放心查看，图片都是本人实地看房拍的。100%，放心来电咨询.<br>【温馨提示】<br>1、凭本人有效身份证原件可免看房。<br>3、如您要看房请提前来电预约，24小时为您服务', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/45d9924ab97c493697c6a6ed94dcd87d.jpg', '["bitehouse/45d9924ab97c493697c6a6ed94dcd87d.jpg", "bitehouse/5f79489597214d0fb1cbc12f4fc4357c.jpg"]', 288, '重庆', 2643, '渝北', '秀丽景苑', '12号楼2单元20404室', 106.6127650, 29.6905050);
