INSERT INTO "public"."house" VALUES (50000010121, 1, '省心租·和润家园二期 1室0厅1卫', 'worry_free_rental', 1, 32, '1室0厅1卫', 'one', 'south', 39.00, 800.00, '此房为中间楼层，3面采光户型，面朝中庭！户型方正带超大阳台。标准单间配套，物管5角钱一平，免停车库！出门即是轻轨站，此小区位于两江新区水土工业园区中心地段，距离悦来会展中心10公里，小区保安24小时巡逻，小区门口有好客万家大型购物生活广场!周围莱宝厂，京东方，联创等！医疗设施：九院（在建），复兴医院，润之康医院！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8d050f5d6de949caae9fb3d11b16fe2f.jpg', '["bitehouse/8d050f5d6de949caae9fb3d11b16fe2f.jpg", "bitehouse/1d3bd0971e5d4a2392a2b65cf9ea8996.jpg"]', 288, '重庆', 2640, '北碚', '和润家园二期', '1号楼3单元30104室', 106.5387800, 29.8336090);
