INSERT INTO "public"."house" VALUES (50000010147, 1, '省心租·泽科空港中心 3室2厅2卫 拎包入住', 'worry_free_rental', 1, 24, '3室2厅2卫', 'three', 'east', 97.00, 2250.00, '【房屋地址】泽科空港中心<br>【房源优势】楼下就是泽科商业。配套成熟，出行便捷<br>【小区环境】小区环境优美，安静。进出有门禁，保安24小时巡逻<br>【房屋装修】精装修<br>【交通情况】<br>本人从事房屋租赁多年，手中有大量房屋租赁信息，浏览更多房源，点击我的头像浏览或咨询。<br>1.本人所发房源均为真实在租房源。<br>2.本人所发照片均为该房源真实照片，绝任何虚假信息。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f1677511eb834e3d94581784c99a7bbf.jpg', '["bitehouse/f1677511eb834e3d94581784c99a7bbf.jpg", "bitehouse/2f65ed971e94443e8941247a4ab201d8.jpg"]', 288, '重庆', 2643, '渝北', '泽科空港中心', '7号楼1单元10101室', 106.6137660, 29.7180730);
