INSERT INTO "public"."house" VALUES (50000010178, 1, '整租·红鼎国际名苑 2室1厅1卫', 'whole', 43, 48, '2室1厅1卫', 'two', 'south', 123.00, 3750.00, '—燕天房产—企业选址—服务第一<br>1.楼盘：红鼎国际A座<br>2.户型：两个室一个大厅，端头户型！<br>3.装修：精装修！适合开店等！<br>4.交通：观音桥步行街，交通四通八达！楼下就是轻轨3号线和9号线！<br>5.室空调配置：空调独立控制，加时<br>6.室网络配置：3网全通，可任意使用，局限<br>7.电梯配置：2部货梯，4部全程电梯<br>8.车位配置：停车位充足，可完全满足本楼客户以及拜访客户使用<br>9.物管：2.5元！<br>10.公司理念：客户至上，精于专业！欢迎致电燕天房产，更多房源请点击我的头像，进入我的！<br>本人专注租赁买卖多年，免看房，免提供专业咨询！本公司资源丰富，主城各区都有住宅，，等！欢迎来电！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8499cf2bba6e4507ba0098bbc61a0af6.jpg', '["bitehouse/8499cf2bba6e4507ba0098bbc61a0af6.jpg", "bitehouse/d2c9f7d3f34c4c57a4b7bf18a49ebb5e.jpg"]', 288, '重庆', 2636, '江北', '红鼎国际名苑', '9号楼3单元33501室', 106.5333440, 29.5754270);
