INSERT INTO "public"."house" VALUES (50000010215, 1, '公寓·金科天宸十一街区 1室1厅1卫', 'apartment', 21, 22, '1室1厅1卫', 'one', 'south', 32.00, 1190.00, '此房源位于微电园轻轨站旁，步行至轻轨站仅500米，楼下就是菜市场和公交站，临近熙街、龙湖U城天街、富力西城广场等大型商场，附近有重庆大、重师大、四川美术学院，出行非常方便，并且本小区绿化面积非常广，有保安24小时巡逻，是您居家的不二选择！我是您的置业顾问小傅，如果您对这套房源不满意，我们还有更多可供您选择，另外本公司还有短租房出租，欢迎您的来电，必将竭诚为您服务！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8f2a61551e2c43cda54a8e9d6c1479f8.jpg', '["bitehouse/8f2a61551e2c43cda54a8e9d6c1479f8.jpg", "bitehouse/20280232f0624bd19b18b705d8ff96ff.jpg"]', 288, '重庆', 2637, '沙坪坝', '金科天宸十一街区', '16号楼1单元10403室', 106.3626150, 29.6129100);
