INSERT INTO "public"."house" VALUES (51010010125, 1, '整租·魅力阳光 1室1厅1卫 有地铁', 'whole_rent', 15, 22, '1室1厅1卫', 'one', 'east', 54.00, 2250.00, '有房源（有安心，有保障）<br>租的安心，家才圆满！<br>我们在您身边的房产专家，“以诚待人、用心做事”！我们始终以“诚信、专业、安全、微笑、超值”的服务理念------帮您找到满意的家！！！<br>楼盘位置魅力之城，出行便利小区周边配套成熟，交通生活方便<br>周边商业配套附近有永辉大型购物超市，多家红旗连锁门店，附近<br>房屋状况:小区环境优雅，家装出租，屋内配套设施齐全，可拎包入住！<br>小区高环境优美宁静和谐，好环境总会给人带来好心情<br>房干净整洁，温馨舒适，窗明几净，就等着您的拎包入住！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/d53765f62f034ed7922b477a3140ca94.jpg', '["bitehouse/d53765f62f034ed7922b477a3140ca94.jpg", "bitehouse/7b3519c8dedb4054b53b18b2f6819d98.jpg"]', 289, '成都', 2674, '成华区', '魅力阳光', '11号楼1单元10902室', 104.1490680, 30.6248910);
