INSERT INTO "public"."house" VALUES (51010010138, 1, '省心租·天府万科云城 1室1厅1卫 可短租', 'worry_free_rental', 21, 30, '1室1厅1卫', 'one', 'south', 25.00, 1350.00, '房屋亮点配套齐全精装修房源描述房屋亮点精装修房源描述一、房源优势：<br>1、全明格局，客厅宽敞大气；<br>2、热门地段交通便利，电梯住宅，拎包入住；<br>3、家私家电齐全，提包入住；4房租面谈。二、户型介绍：<br>1、格局方正，使用率高达90%.<br>2、客厅宽敞舒适、落地阳台让充足的阳光不留余地的闯进来.<br>3、厨房宽敞，让您和家人有足够的空间展现私家厨艺.<br>4、连接客厅和厨房之间是您和家人享受美味的餐厅，让您热情的招待亲朋好友.<br>三、社区介绍：<br>1、环境优美，适宜居住，人文素质高，物业管理完善，小区治安好.<br>2、小区属于低密度社区，非常适宜居住.<br>周边有大型超市家乐福，还有各种大型火锅店，KTV，足浴。一号线地铁站就在小区附近，还有各路公交车。周边有大型菜市场，以及各类小型私人菜市场，还有各种生鲜超市，红旗连锁超市，有卫生站，有健身等', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/eb1104bf11b747a99b3267b06c5f564e.jpg', '["bitehouse/eb1104bf11b747a99b3267b06c5f564e.jpg", "bitehouse/2c50a3aaaf904dd0aed9d27bb1947bb7.jpg"]', 289, '成都', 2679, '双流区', '天府万科云城', '15号楼1单元10803室', 104.0869900, 30.3899530);
