INSERT INTO "public"."house" VALUES (51010010182, 1, '省心租·上游小区(南区) 2室2厅1卫 可短租', 'worry_free_rental', 5, 11, '2室2厅1卫', 'two', 'south', 72.00, 1400.00, '1、房子是居家装修套二，家具家电齐全，可拎包入住。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a305120047914cf999904636f08e7deb.jpg', '["bitehouse/a305120047914cf999904636f08e7deb.jpg", "bitehouse/2aa98a9871734a209dd0201ce15c1058.jpg"]', 289, '成都', 2685, '都江堰市', '上游小区(南区)', '11号楼1单元10101室', 103.6594570, 31.0073890);
INSERT INTO "public"."house" VALUES (51010010183, 1, '整租·绿地世纪城 3室1厅1卫 可月付', 'whole_rent', 16, 27, '3室1厅1卫', 'three', 'south', 86.00, 2450.00, '一，房屋介绍<br>1、此房格局方正，中间楼层，性价比超高。<br>2、宽敞大气，精装修，拎包入住!<br>3、全新家具，搭配合理且符合美学!<br>二、户型介绍:<br>1、宽敞舒适、阳光非常充足，阳台视野宽敞!<br>2、卧室舒适整洁，居家必选。<br>3、厨房使用率高，让您和家人有足够的空间展现私家厨艺<br>三、社区介绍:<br>1、社区环境好，环境优美，适宜居住，人文素质高，物业管理完善;小区的绿化率高。<br>2、多条公交线路通过;交通便利，出行方便!', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/2f242f52adc54db08fbbf120f6efd6e4.jpg', '["bitehouse/2f242f52adc54db08fbbf120f6efd6e4.jpg", "bitehouse/94510209278a45f5bdeae398150538d7.jpg"]', 289, '成都', 2672, '金牛区', '绿地世纪城', '14号楼1单元11501室', 104.0788690, 30.7209100);
