INSERT INTO "public"."house" VALUES (51010010249, 1, '整租·世茂璀璨天城 4室2厅2卫 拎包入住', 'whole_rent', 27, 33, '4室2厅2卫', 'four', 'south', 160.00, 6200.00, '专注高端豪宅租赁，任何区域均可匹配<br>专注于高端不动产用真诚与品质为您服务<br>房源描述<br>【小区环境】地段环境安静优雅小区干净整洁大气<br>【房屋状况】简约风格设计<br>【房内设备】全进口设备，设备齐全，咖啡机，净水器，音响，中央空调.<br>【户型结构】朝南户型，方正大气。<br>【价格情况】关于房源价格，房东的意思是只要好好爱护房子还可谈！！<br>【售后服务】此房只要你入住进去，里面出现任何问题房东都可以一一帮你解决。<br>服务范围', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/2af902293654432381b084ec2aef167c.jpg', '["bitehouse/2af902293654432381b084ec2aef167c.jpg", "bitehouse/7bd6e224526b438c93a2384541ee12fa.jpg"]', 289, '成都', 2675, '龙泉驿区', '世茂璀璨天城', '9号楼2单元20403室', 104.1904990, 30.5804650);
