INSERT INTO "public"."house" VALUES (51010010297, 1, '整租·新熙门财富中心(商住楼) 1室1厅1卫 可月付', 'whole_rent', 15, 30, '1室1厅1卫', 'one', 'south', 56.00, 2950.00, '期待您的浏览，<br>选择家，请选择小姐姐为您捷成服务。<br>此房不满意，可为您匹配适合您的房源可月付，可季度付，水电气民用<br>周围配套:出行交通方便，配套设施齐全.小区安保齐全物管用心,环境优美干净整洁,居家优选。<br>房屋配套:房屋干净整洁家具家电齐全保养好.房屋通<br>风透气视野开阔采光好.拎包入住,省心放心。<br>可能此房信息不够详细,如有任何问题，我会详细、耐心的为您解答<br>如果此房您不满意，请与我联系，我会根据您的需求给您推荐合适的您的房子<br>我们坚信，租客就是上帝，合同不是结束！而是开始<br>真实图片，欢迎咨询！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/004a579b33f442d1966c0d3504c805bc.jpg', '["bitehouse/004a579b33f442d1966c0d3504c805bc.jpg", "bitehouse/770016ac1c334363a80924bdbb69943d.jpg"]', 289, '成都', 2672, '金牛区', '新熙门财富中心(商住楼)', '10号楼3单元30404室', 104.0459700, 30.6837510);
