INSERT INTO "public"."house" VALUES (51010010299, 1, '整租·嘉年华青年城smart公寓 1室1厅1卫 可月付', 'whole_rent', 13, 30, '1室1厅1卫', 'one', 'south', 30.00, 1600.00, '房屋亮点配套齐全精装修房源描述房屋亮点精装修房源描述一、房源优势：<br>1、全明格局，客厅宽敞大气；<br>2、热门地段交通便利，电梯住宅，拎包入住；<br>3、家私家电齐全，提包入住；4房租面谈。二、户型介绍：<br>1、格局方正，使用率高达90%.<br>2、客厅宽敞舒适、落地阳台让充足的阳光不留余地的闯进来.<br>3、厨房宽敞，让您和家人有足够的空间展现私家厨艺.<br>4、连接客厅和厨房之间是您和家人享受美味的餐厅，让您热情的招待亲朋好友.<br>三、社区介绍：<br>1、环境优美，适宜居住，人文素质高，物业管理完善，小区治安好.<br>2、小区属于低密度社区，非常适宜居住.<br>周边有大型超市家乐福，还有各种大型火锅店，KTV，足浴。一号线地铁站就在小区附近，还有各路公交车。周边有大型菜市场，以及各类小型私人菜市场，还有各种生鲜超市，红旗连锁超市，有卫生站，有健身等', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/63476f6132584435b044873a3895d48e.jpg', '["bitehouse/63476f6132584435b044873a3895d48e.jpg", "bitehouse/feb00d1ff09747ab9c8e7147b3f9b85e.jpg"]', 289, '成都', 2679, '双流区', '嘉年华青年城smart公寓', '12号楼3单元30603室', 104.0798920, 30.5357290);
