INSERT INTO "public"."house" VALUES (51010010340, 1, '公寓·金地天府城(商住楼) 2室2厅1卫', 'apartment', 17, 32, '2室2厅1卫', 'two', 'south', 71.00, 2400.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于高新区东寺南一路18号，南延线商圈。<br>【户型面积】<br>出租一套71平米的2室2厅1卫，南北朝向，带电梯，采光通风良好，居住舒适。<br>【家具家电】<br>出租房配备齐全，有冰箱、洗衣机、热水器等生活设施，还有宽带、沙发等舒适家居。厨房设施齐全，可做饭，有油烟机、燃气灶，让您生活便捷舒适。<br>【周边配套】<br>购物中心距离成都三利爱琴海购物中心仅608米，购物休闲便捷。超市周边有AA金地公寓1栋2楼超市、金地天府城超市、禾林超市等，满足日常生活所需。公园距离成都极地海洋公园250米，还有万科海悦汇城东区-四期、锦恩体育公园、天府新区消防文化公园等。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e30627eef59a4676830b1a924e051129.jpg', '["bitehouse/e30627eef59a4676830b1a924e051129.jpg", "bitehouse/6e5128aa887b42f6bd5227896e18d1ef.jpg"]', 289, '成都', 2679, '双流区', '金地天府城(商住楼)', '13号楼3单元31702室', 104.0738560, 30.4965250);
