INSERT INTO "public"."house" VALUES (51010010368, 1, '省心租·清淳家园二期A区 2室2厅1卫', 'worry_free_rental', 16, 18, '2室2厅1卫', 'two', 'south', 75.00, 2248.00, '再好的房源介绍都不如别人的虚假价格！！！<br>好吧！那就这样吧！！！<br>或许我的实图实价已经不适合现在这个社会！！！<br>或许这个网络已容不下我们这种诚实的人！！！<br>不好意思你们喜欢的虚假价格我这里没有！！！<br>我的所有房源照片都是实拍的，房子照片一致！！！<br>所有价格都是可以直接签合同的价格，绝不拉稀摆带！！！<br>话已至此，自己选择吧！！！！！！！！！！！！！！！！！<br>！！！！！！！！！！！！！！！！！！！！！！！！！！！！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/382a75a996014efa8b09778de2408adb.jpg', '["bitehouse/382a75a996014efa8b09778de2408adb.jpg", "bitehouse/ce590783c2a447b89635a5582d3b21d3.jpg"]', 289, '成都', 2672, '金牛区', '清淳家园二期A区', '15号楼3单元31502室', 103.9783610, 30.6998260);
