INSERT INTO "public"."house" VALUES (51010010377, 1, '公寓·鑫苑名家新青年 1室0厅1卫 家具家电齐全', 'apartment', 18, 35, '1室0厅1卫', 'one', 'south', 40.00, 1350.00, '真诚服务始终如一因为专注所以专业<br>给您一个温馨的家给您带来专业和贴心的服务<br>房屋简介<br>此房临近地铁，紧靠幸福梅林温馨舒适，拧包入住随时看房<br>周边配套<br>商业三圣乡农贸市场，卓锦城菜市场，舞东风，红旗超市(伊藤,永辉<br>交通40、56、332、343、533、541、230、133，196和社区巴士等路公交车直达，地铁二号线洪河站，距离约800米<br>学校四川师范大学，盐道街小学，川师附属中学，川师附属小学，成都伊顿国际幼儿园，成都育才七中，三圣乡小学，树德中学<br>银行建设银行，农业银行，中国银行，工商银行，邮政储蓄<br>更多房源可随时来电*真诚为你服务！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/51e44084f1dd4278bbe766a99fd2ad9d.jpg', '["bitehouse/51e44084f1dd4278bbe766a99fd2ad9d.jpg", "bitehouse/76ed3c9440cf4317ac1cccc421006896.jpg"]', 289, '成都', 2670, '锦江区', '鑫苑名家新青年', '6号楼2单元21104室', 104.1420400, 30.5977020);
