INSERT INTO "public"."house" VALUES (51010010484, 1, '省心租·临江丽苑三期A区 2室2厅1卫', 'worry_free_rental', 1, 18, '2室2厅1卫', 'two', 'south', 80.00, 1800.00, '房子户型方正，适合居住！小区物业费便宜，水电气民用，附近有多路公交通往双流华阳和市区，离地铁8号线川大江安站和文星站都很近，出行非常方便！<br>生活所需物品楼下就能买到，附近电影院，公园，医院，商场，字校一应俱全，生活相当便利！<br>如果你正在找房，或者不知道住哪里，只要你来电，专业给您推荐更好的选择，愿您落脚在这座温馨的都市，从此不在为找房租房这件事而烦恼，相信我欢迎咨询来电，看房约起来！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/b7ec66d73e15488ebcb2cc6ef9d000e6.jpg', '["bitehouse/b7ec66d73e15488ebcb2cc6ef9d000e6.jpg", "bitehouse/73c3dc3a803b42fbb02229def1a011fd.jpg"]', 289, '成都', 2679, '双流区', '临江丽苑三期A区', '15号楼1单元10104室', 104.0037440, 30.5433170);
