INSERT INTO "public"."house" VALUES (51010010508, 1, '省心租·柳江新居五期 2室2厅1卫 有地铁', 'worry_free_rental', 11, 18, '2室2厅1卫', 'two', 'east', 84.00, 2350.00, '周边交通便利紧邻城市主干道享受地铁、数十余公交线路等便利的交通设施专业打造一个纯居住的小区，绿化率高，社区环境好;经典户型，，客厅卧室全带阳台飘窗，明厨明卫，居住非常舒适，利用率超高！租价合理，非常超值，业主诚意出租，看房随时！欢迎您点击我的头像进入我的主页，有更多超值户型等您选择，期待您的来电！！另本人郑重承诺将为您的电话号码提供保密，以免让您接到不必要的打扰电话！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/2484e1083fa64b358f9864541475940e.jpg', '["bitehouse/2484e1083fa64b358f9864541475940e.jpg", "bitehouse/3341597c82b6471780807e65bab205b9.jpg"]', 289, '成都', 2670, '锦江区', '柳江新居五期', '12号楼3单元30301室', 104.0971910, 30.6042540);
