INSERT INTO "public"."house" VALUES (51010010530, 1, '省心租·龙锦雅苑 1室1厅1卫 拎包入住', 'worry_free_rental', 5, 11, '1室1厅1卫', 'one', 'south', 47.00, 1400.00, '一.房源优势:<br>1此房格局方正,采光好,室内干净整洁.性价比高。<br>2.照片全部为实拍,真实图片,房间内部设施一模一样。<br>二.小区介绍:<br>1.社区环境幽美，适宜居住，物业管理完善.<br>2.物业费只要0.6元/m²,水电气民用,生活成本低。<br>三.交通便利:<br>1.小区门口就有公交,周边生活配套设施齐全交通便利,节约您的宝贵时间。<br>2.便利的购物场所是您的生活保障。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/0c642a9ff95a42ddbc39c3a0ec2c50da.jpg', '["bitehouse/0c642a9ff95a42ddbc39c3a0ec2c50da.jpg", "bitehouse/2b06f3b9f2bc466db0841545397a30b3.jpg"]', 289, '成都', 2674, '成华区', '龙锦雅苑', '2号楼3单元30403室', 104.1737840, 30.6948100);
