INSERT INTO "public"."house" VALUES (51010010537, 1, '整租·恒大名都 2室1厅1卫', 'whole_rent', 11, 30, '2室1厅1卫', 'two', 'south', 72.00, 2500.00, '1.杜绝虚假房源，浪费彼此时间！<br>2.可月付，季付，半年付，年付，标价均为年付。根据您的需求决定！<br>3.诚信出租，提供品质生活！<br>4.配套完善，家电家居齐全，空调，冰箱，洗衣机，宽带，热水器应有尽有！可直接拎包入住<br>5.免费家电维修：家具家电有问题，24小时有专业人员上门维修，生活有保障！<br>6.交通便利，离地铁口，公交站近，出行方便！<br>7.周边各种超市，商场应有尽有，生活设施便利！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/018d7878a4ab4a7e974b8246753622fc.jpg', '["bitehouse/018d7878a4ab4a7e974b8246753622fc.jpg", "bitehouse/4444e96856e3443f953ada7e219409d2.jpg"]', 289, '成都', 2679, '双流区', '恒大名都', '17号楼2单元21002室', 104.0800450, 30.4869120);
