INSERT INTO "public"."house" VALUES (52010010002, 1, '个人房源·花果园一期 1室1厅1卫 拎包入住', 'personal_house', 26, 43, '1室1厅1卫', 'one', 'south', 19.00, 698.00, '房屋介绍<br>1精装修配套齐全随时可以入住<br>2.本人手上有很多房源，各个区都有，比如花果园一期<br>A北A南B北B南E区C区J区M区L区T区Q区V区R区都有<br>各种各样的发型都有单间合租一室一厅单间带卫两室<br>整租三室整租、公寓．<br>3.各种装修各种价位都有，有几百间房子出租总有一间<br>适合你的，价格便宜又实惠，找我租房无忧，不用东<br>奔西跑。<br>4、本人手上还有大量的房源我们拥有贵阳南明区花果<br>园90%以上的房源，押。<br>一付．<br>一无中介可随时提供<br>蒂看', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9b95d1bdc8f544a1a358f6eb4e7712cc.jpg', '["bitehouse/9b95d1bdc8f544a1a358f6eb4e7712cc.jpg", "bitehouse/0e7aad8bc450469b910b8199d3cbf4f3.jpg"]', 310, '贵阳', 2853, '南明区', '花果园一期', '6号楼3单元30104室', 106.6844920, 26.5675400);
