INSERT INTO "public"."house" VALUES (52010010036, 1, '整租·中天金融城N区(商住楼) 1室1厅1卫 可月付', 'whole', 5, 40, '1室1厅1卫', 'one', 'south', 40.00, 1149.00, '叮咚!有金屋出租哦!贵阳市周边。观山湖区、花果园<br>1.房屋精装修!拎包入住哦<br>2.不豪华，但温馨[吃瓜][吃瓜]<br>3.家电有:冰箱、洗衣机、电暖炉、吸烟机<br>4.交通便利，近地铁站附近<br>5.南北通透，适合:情侣国蜜、哥们居住。<br>6.接受长短租，可押一付一。价格特实惠<br>7.小区周边配套设施齐全，幼儿园小学廟围<br>菜价便宜，适合生活，小区门口就有很多小型<br>购物超市<br>(8)如果上班累的话，不妨住一个温馨的小屋给你生活带来温暖，带来安全感。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/03fe8685046c402482eb24bc3ef88757.jpg', '["bitehouse/03fe8685046c402482eb24bc3ef88757.jpg", "bitehouse/05fc3362029d4451920725c0eb470644.jpg"]', 310, '贵阳', 2858, '观山湖区', '中天金融城N区(商住楼)', '12号楼2单元20201室', 106.6518040, 26.6564380);
