INSERT INTO "public"."house" VALUES (53010010030, 1, '个人房源·绿地巫家坝壹号 4室2厅2卫 无中介费', 'personal_house', 9, 23, '4室2厅2卫', 'four', 'south', 143.00, 2450.00, '房源信息真实有效，欢迎你实地勘察<br>1、0中间费，可以押一付一<br>2、房租月付，无压力。<br>3、房屋为精装修，屋内装饰比较漂亮、时尚、清新，具体的看图片，图片为房屋的实际图片。<br>4、屋内配有床、衣柜、沙发，餐桌，等家具，拎包即可入住，另外配有洗衣机、热水器、电视、冰箱。<br>5、可以做饭。<br>6、随时可以看房！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c21c80cb459543bb9bf3bcd7ca199715.jpg', '["bitehouse/c21c80cb459543bb9bf3bcd7ca199715.jpg", "bitehouse/d3d238495db04e65b2aa8a9edb00feaf.jpg"]', 319, '昆明', 2943, '官渡区', '绿地巫家坝壹号', '20号楼1单元10801室', 102.7364210, 24.9810900);
