INSERT INTO "public"."house" VALUES (53010010037, 1, '个人房源·海伦国际曼哈顿 1室1厅1卫 可月付', 'personal_house', 14, 48, '1室1厅1卫', 'one', 'south', 46.00, 1400.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于官渡区永中路，属于海伦国际商圈。<br>【户型面积】<br>出租一套46平米的1室1厅1卫，南北朝向，带电梯，舒适宜居。<br>【家具家电】<br>出租温馨舒适房屋，配备齐全家具家电，尽享便捷生活。冰箱、洗衣机、热水器等家电一应俱全，沙发、可做饭等家具舒适实用，宽带、油烟机、燃气灶等配套设施完善，让您居住无忧。<br>【周边配套】<br>房源位于商业繁华地带，周边有昆明海乐世界购物中心、海乐城等购物中心，距离昆明海乐世界购物中心177米，距离海乐城555米。附近有多家超市，如中通菜鸟驿站超市、维铂生活等，距离中通菜鸟驿站超市134米，距离维铂生活146米。还有多家超市，如永辉超市、鸿运超市、小兰超市等，距离永辉超市157米，距离鸿运超市268米，距离小兰超市364米。周边还有东沟公园、长江航道林、如意楼副食店、官渡区世纪城如意园重庆火锅等休闲场所，距离东沟公园988米，距离长江航道林1086米，距离如意楼副食店1179米，距离官渡区世纪城如意园重庆火锅1248米。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a8faa3fed9e845cbac0e94c1dbd37276.jpg', '["bitehouse/a8faa3fed9e845cbac0e94c1dbd37276.jpg", "bitehouse/8592e6086bde4be187233bef64a0705c.jpg"]', 319, '昆明', 2943, '官渡区', '海伦国际曼哈顿', '1号楼1单元10404室', 102.7421440, 24.9717640);
