INSERT INTO "public"."house" VALUES (53010010050, 1, '个人房源·海埂路223号小区 3室2厅2卫 可短租', 'personal_house', 15, 30, '3室2厅2卫', 'three', 'south', 26.00, 650.00, '1、配套设施齐全，联系了一年的保洁，定时打扫。合作了专门的供应商，东西损坏包维修，包更换。<br>2、正朝南，采光充足，房间采光明亮通透。通风顺畅，冬暖夏凉。<br>3、正规主卧，隔音好，隐私性强。<br>3、价格合理、多种付款方式，极大的缓解现金压力。<br>4、室友都是年轻人，应届生，很好沟通，素质高，减少生活上的麻烦。<br>5、小区内安防设施齐全，物业管理完善，安全性高。<br>6、绿化良好，平时锻炼遛弯方便，说不定还有一段美丽的邂逅呢。<br>7、地区繁华，周边有超市、银行、餐馆、KVT、网吧、酒吧、健身房、公园等。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/23df84d35da7471c812569c878eab70e.jpg', '["bitehouse/23df84d35da7471c812569c878eab70e.jpg", "bitehouse/7276f048cde34106bb429cae2f9966e3.jpg"]', 319, '昆明', 2944, '西山区', '海埂路223号小区', '2号楼1单元11304室', 102.7094770, 25.0101900);
