INSERT INTO "public"."house" VALUES (53010010090, 1, '省心租·凤凰小区 1室1厅1卫', 'worry_free_rental', 4, 9, '1室1厅1卫', 'one', 'south', 40.00, 1050.00, '昆明四区合租】五华区、西山区、盘龙区、官渡区均有房源<br>【押一付一】不绑定任何形式的贷款软件，不使用任何分期软件，房租直接打给公司<br>【租期灵活】部分房源有租期长短，均可选择，提供特殊情况，特殊处理<br>【家具电器】所有房源，家电齐全，冰箱，洗衣机，热水器。也有带空调的房间，电脑桌椅床衣柜齐全<br>【价格便宜】部分单间价格在600--1300元/月（因空间大小，朝向，装修定价)<br>【包含费用】合租包含水电宽带<br>【免费带看】全程免费带看，免费提供入住，退房的服务<br>【售后保障】公司提供免费维修服务，只要不是恶意损坏，公司都会免费上门维修<br>【随时带看】，', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8b6f6cca79e043079b9fe00490eab619.jpg', '["bitehouse/8b6f6cca79e043079b9fe00490eab619.jpg", "bitehouse/c47238f2cdaf42a286f4f8a936923acd.jpg"]', 319, '昆明', 2942, '盘龙区', '凤凰小区', '14号楼1单元10303室', 102.7203280, 25.0471220);
INSERT INTO "public"."house" VALUES (53010010091, 1, '个人房源·华城花园 1室1厅1卫 可月付', 'personal_house', 5, 10, '1室1厅1卫', 'one', 'south', 36.00, 600.00, '1无中介，（随时可看房）2.房租无压力，所有房源‮可均‬押一付一，部‮房分‬源带独立阳台、卫生间。3.‮包拎‬入住，设施齐全。全新装修，带全套家具。室内统一配置：床、床头柜、衣柜、电‮桌脑‬椅、冰箱、洗衣机、热水器、100M光纤宽带。4．每月有‮次两‬家政定期保洁，全区高速wifi覆盖，不限流量时间。房源范围北市区，五华区，官渡区，西山区，小西门‮大云‬医院附近、昆明站附近、等几‮套百‬房源，全新家具电器，真实图片，押‮付一‬一，小区环‮优境‬雅', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/26f11203777d4dae83f656372db1e172.jpg', '["bitehouse/26f11203777d4dae83f656372db1e172.jpg", "bitehouse/b8b6f4111cf64f2da326fba87a7cde17.jpg"]', 319, '昆明', 2943, '官渡区', '华城花园', '12号楼3单元30104室', 102.7898060, 24.9351350);
