INSERT INTO "public"."house" VALUES (53010010157, 1, '整租·海畔湾云骏苑 2室2厅1卫', 'whole', 23, 33, '2室2厅1卫', 'two', 'east', 80.00, 1650.00, '欢迎光临同享好房中介小余的网店，本人发布的所有房源图片和视频均是现场真实拍照，真实价格！房源介绍：小区都是电梯房，民用水电，采光好，干净清爽，距离三号地铁、马街菜市场、医院、公园近，小区内配有幼儿园，紧邻二环，配套齐全，生活出行方便。精装修，大部分房源属首租或是二次出租，停车位有地下负一负二两层，车位多不固定。有钥匙，随时可以实地看房。我们公司在新蕊苑5栋207室。我公司主要负责海畔湾新蕊苑、云骏苑、鸣凤苑、书香云海，小区有多套房源在租，欢迎您来电或是点击我的头像24小时免费在线咨询。我坚持以诚信、务实、高效率为每一位顾客提供诚信服务。了解更多房源信息可点击我的头像进入我的微店查看。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ee7febface244ce9acb2b5ba37cdd003.jpg', '["bitehouse/ee7febface244ce9acb2b5ba37cdd003.jpg", "bitehouse/eb4cff4bf17140ea8d82046c13aa857a.jpg"]', 319, '昆明', 2944, '西山区', '海畔湾云骏苑', '6号楼3单元31602室', 102.6430600, 25.0267940);
