INSERT INTO "public"."house" VALUES (53010010189, 1, '整租·兰亭广场 1室1厅1卫 有地铁', 'whole', 8, 26, '1室1厅1卫', 'one', 'east', 43.00, 1550.00, '1.小区绿化高，环境清静，阳光充足、南北通透、空气流通，居住人群人文素质高，性价比高。配套介绍：配套齐全、生活所需一应齐全，便利的生活触手可及小区附近有大型商场、超市等（居家购物方便至极）；2、位于小区不远有银行、医院、学校、保险公司等；3、小区旁有小学、中学（孩子上学方便）；4、距离小区不远有饭店、酒楼、餐馆（招待朋友不愁）；5、交通介绍：地理位置得天独厚，私家车和公共交通都能方便出行，各条公交都有。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ec15cf535ccd44fbbbeae51613de7180.jpg', '["bitehouse/ec15cf535ccd44fbbbeae51613de7180.jpg", "bitehouse/91fda1a22b884d90adb3e64046b67ef6.jpg"]', 319, '昆明', 2944, '西山区', '兰亭广场', '4号楼3单元30302室', 102.6515260, 25.0466980);
