INSERT INTO "public"."house" VALUES (53010010200, 1, '省心租·海运花园 3室2厅1卫 有地铁', 'worry_free_rental', 5, 20, '3室2厅1卫', 'three', 'south', 122.00, 2350.00, '非常感谢您的光临！让您在繁忙的城市生活中找到家的温暖。<br>【地理位置】<br>位于官渡区彩云北路,近广福路，紧邻新亚洲体育城商圈。<br>【户型面积】<br>122平舒适3室2厅1卫，南北朝向，带电梯，宜居宜。<br>【家具家电】<br>出租房配备齐全，有冰箱、洗衣机、热水器等生活设施，宽带网络覆盖，沙发舒适，提供做饭设备，让您尽享便捷生活。<br>【周边配套】<br>该小区周边拥有丰富的商业配套，包括万动汇运动公园、四季联家超市(海运小区店)、豪琪日用百货、新维客超市、优乐购超市、众福园超市(子君村店)等超市，满足您的日常生活所需。此外，还有悦成国际商业广场、俊发新螺蛳湾国际商贸城、星世界商业广场等购物中心，满足您的购物需求。距离悦成国际商业广场515米、俊发新螺蛳湾国际商贸城763米、星世界商业广场937米。此外，还有普键金福地医院、昆明市第一人民医院星耀医院等综合医院，为您的健康保驾护航。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/ca07c6680389469a86c75de8bb2de989.jpg', '["bitehouse/ca07c6680389469a86c75de8bb2de989.jpg", "bitehouse/037f9ba093334c1e814f48f0c3ad2116.jpg"]', 319, '昆明', 2943, '官渡区', '海运花园', '14号楼3单元30501室', 102.7718370, 24.9461610);
