INSERT INTO "public"."house" VALUES (53010010228, 1, '省心租·晨光大道 3室2厅2卫', 'worry_free_rental', 2, 6, '3室2厅2卫', 'three', 'south', 142.00, 2700.00, '核心卖点（云波小学-财大）<br>1、户型：3室2厅2卫2阳台，南北向，户型方正无<br>2、装修：精装修性价比高，房子清爽干净，<br>3、小区：物业1.6元/平米，建房年代2006年，绿化高<br>4、生活方便：出门就有财富中心商业圈，周边多个农贸市场（小庄农贸市场、菜蓝子海鲜农贸市场、罗丈村农贸市场）', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e934000b551848dfa10ee2fddf166a1e.jpg', '["bitehouse/e934000b551848dfa10ee2fddf166a1e.jpg", "bitehouse/e7099c251af94738beddb0dc4827e4b1.jpg"]', 319, '昆明', 2942, '盘龙区', '晨光大道', '9号楼3单元30103室', 102.7473880, 25.0759450);
