INSERT INTO "public"."house" VALUES (53010010230, 1, '省心租·翠羽丹霞 1室2厅1卫 拎包入住', 'worry_free_rental', 5, 22, '1室2厅1卫', 'one', 'south', 57.00, 1750.00, '西山区丹霞路棕树营小区翠羽丹霞，精装一室二厅一厨一卫，带家具家电，无遮挡采光好，靠近地铁三号线市体育馆站。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c574eaea9839428cba0a7efed74a783e.jpg', '["bitehouse/c574eaea9839428cba0a7efed74a783e.jpg", "bitehouse/6ac35f608f1c41c283db67d35fad9468.jpg"]', 319, '昆明', 2944, '西山区', '翠羽丹霞', '15号楼2单元20403室', 102.6843490, 25.0393960);
INSERT INTO "public"."house" VALUES (53010010231, 1, '个人房源·龙湖天第 1室1厅1卫 无中介费', 'personal_house', 22, 24, '1室1厅1卫', 'one', 'south', 33.00, 1500.00, '房屋亮点邻地铁押一付一配套齐全精装修<br>1，房屋属于公司自有房源，无中介<br>2，付款方式灵活，可月付，租期长，图片均为真实拍摄，房间<br>朝向好，光照充足，也可做饭，另有简约壁画，舒适温馨<br>3，拎包入住，设施齐全。全套全新家具家电，房间统一配备有床，床头柜，衣柜，洗衣机，冰箱，热水器，晾衣架，窗帘等;<br>4，高档小区电梯房，环境优美绿化好，周边餐饮，水果店，夜宵店，学校，银行，医院一应俱全，放心入佳;<br>5，管家服务，故障及时维修，投诉建议立即响应;<br>6，为保证您有安静舒适安全高质量的入佳体验，远离群相生活，告别脏乱差。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c1767712590c4d699e2e84e91eaf7570.jpg', '["bitehouse/c1767712590c4d699e2e84e91eaf7570.jpg", "bitehouse/2cebb8a73a974af6a455c4d7af1f5b6e.jpg"]', 319, '昆明', 2943, '官渡区', '龙湖天第', '2号楼1单元11302室', 102.7294330, 25.0279600);
