INSERT INTO "public"."house" VALUES (53010010259, 1, '整租·万科金域国际(一期) 2室2厅1卫 拎包入住', 'whole', 32, 34, '2室2厅1卫', 'two', 'south', 70.00, 2050.00, '.房子户型方正，朝向好，毛坯新房。<br>2.小区绿化率高，环境优雅，非常适合居住。<br>3.小区门口就是兰亭购物广场，生活购物方便', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f4ddc388584b4ae78fb280de1fa707af.jpg', '["bitehouse/f4ddc388584b4ae78fb280de1fa707af.jpg", "bitehouse/7f33b436b9c943c0ae57a3357a184b52.jpg"]', 319, '昆明', 2941, '五华区', '万科金域国际(一期)', '11号楼3单元32102室', 102.6550460, 25.0529490);
