INSERT INTO "public"."house" VALUES (61010210031, 1, '整租·中菲钻石星座 1室1厅1卫 可短租', 'whole_rent', 17, 26, '1室1厅1卫', 'one', 'south', 46.00, 1550.00, '装修描述<br>房子是全新精装修的，业主一直自住，所以装修保持的很好，房子里面干净温馨，家具家电齐全。拎包入住<br>周边配套', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8804950f00db40f5bfb7035158b864e3.jpg', '["bitehouse/8804950f00db40f5bfb7035158b864e3.jpg", "bitehouse/b6cd8e45988c4050b16f0cf28bd1dc73.jpg"]', 342, '西安', 3144, '新城区', '中菲钻石星座', '17号楼1单元11002室', 108.9980770, 34.2708860);
