INSERT INTO "public"."house" VALUES (61010310068, 1, '省心租·泰华世纪新城 2室1厅1卫 可短租', 'worry_free_rental', 21, 26, '2室1厅1卫', 'two', 'south', 103.00, 2950.00, '(1)业主诚意出租；低楼层，装修精美，可直接入住，希望您不要错过这次机会。<br>(2)户型方正，通风、采光良好；家具家电齐全，房子干净清爽拎包入住；<br>(3)装修精美，都是环保材料;<br>(4)房屋格局好，室内无浪费面积；<br>(5)钥匙在手，随时看房；<br>(6)社区小区周边购物方便；<br>(7)周边绿化完整。<br>(8)停车位充足：小区有停车位，目前尚有空闲，价格优美；', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/c348b070617141299213a05ecacd7a9c.jpg', '["bitehouse/c348b070617141299213a05ecacd7a9c.jpg", "bitehouse/e28ec5455b6b4a418933e47daea0e9e0.jpg"]', 342, '西安', 3145, '碑林区', '泰华世纪新城', '19号楼1单元11804室', 108.9545030, 34.2424740);
