INSERT INTO "public"."house" VALUES (61011110029, 1, '合租·浐河雅居 3室2厅2卫 有地铁', 'share_rent', 18, 33, '3室2厅2卫', 'three', 'south', 25.00, 700.00, '支付宝合作公寓~全国连锁品牌合租公寓~一线城市均有房源~暖气费物业费网费全免~品质好房拎包入住~免租金活动火热持续中~全国高质量房源任您挑选~', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8f2a61551e2c43cda54a8e9d6c1479f8.jpg', '["bitehouse/8f2a61551e2c43cda54a8e9d6c1479f8.jpg", "bitehouse/94510209278a45f5bdeae398150538d7.jpg"]', 342, '西安', 3147, '灞桥区', '浐河雅居', '10号楼1单元11801室', 109.0445790, 34.2759090);
