INSERT INTO "public"."house" VALUES (61011110066, 1, '省心租·半坡国际广场 2室2厅2卫 有地铁', 'worry_free_rental', 20, 33, '2室2厅2卫', 'two', 'south', 20.00, 830.00, '面对网上真真假假的房源信息！您是否感觉找房子很辛苦，所以找一个诚实守信的经纪人的确非常重要，只要您诚心或者致电告诉我您租房需求，我定帮您-只选择您-需要的，为您更好的节省时间、欢迎随时致电。永远在线！房屋概况：1.室内视角：精装修，全配，卧室朝南带阳台，房屋透气性和采光度很高。2.配套设施齐全，干净明亮宽敞，给人以温馨舒适干净的居家房屋，房间保养得好。3.窗帘门窗桌椅等各色物品都室业主精心配备的，舒适温馨。4.看房方式：房东信任我们，已将钥匙交与我们店管理，看房方便。5.简单收拾即可随时入住房间不等人，有意向，马上带您看房亲自拍照验房，以专业的服务，得到您的认可！', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a4712ddecbb94e54930d48f43e987559.jpg', '["bitehouse/a4712ddecbb94e54930d48f43e987559.jpg", "bitehouse/a53ee491e36b482f8447fb335ebf4879.jpg"]', 342, '西安', 3147, '灞桥区', '半坡国际广场', '14号楼1单元11503室', 109.0529670, 34.2743350);
