INSERT INTO "public"."house" VALUES (61011310025, 1, '整租·兰乔圣菲广场 1室1厅1卫', 'whole_rent', 5, 32, '1室1厅1卫', 'one', 'south', 51.00, 1950.00, '1服务宗旨：用专业让你信服<br>用真诚让你感动<br>用服务改变生活<br>本公司有大量（西高新，锦业路，西万路口，太白南路，科技六路）附近房源<br>2.户型格局分布合理，居住舒适，难得的好房<br>3.精致装修此房装修相当不错，装修材料采用全部环保材料<br>4.配备齐全室内所需家具家电全齐，可拎包入住无需带除衣物外的任何东西<br>5.社区成熟小区目前周边学校，公园，购物，公交车站6路、204路、900路、311路、312路、313路、200路、716路、225路<br>6.自我介绍我热情周到细致的服务，赢得业主和客户的认可我主要负责的楼盘有（万达天樾，建邦华庭，木塔南苑，木塔永和坊，香榭兰岛，大华阳光曼哈顿，兰乔圣菲，金泰家假日花城，融侨馨苑，紫薇尚层，和城国际，晶城秀府，裕昌太阳城，高新领域江林新城坤元time天正幸福里立丰国际金石柏朗等等）', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a8faa3fed9e845cbac0e94c1dbd37276.jpg', '["bitehouse/a8faa3fed9e845cbac0e94c1dbd37276.jpg", "bitehouse/50cefb8695fe4da193442b89c3861ab6.jpg"]', 342, '西安', 3149, '雁塔区', '兰乔圣菲广场', '13号楼3单元30303室', 108.9051670, 34.2079760);
