INSERT INTO "public"."house" VALUES (61011310029, 1, '个人房源·长丰园二区 1室1厅1卫 无中介费', 'personal_house', 14, 30, '1室1厅1卫', 'one', 'south', 35.00, 1400.00, '1.房屋精装修，布局合理，温馨舒适有热水可洗澡，有天然气暖气空调。<br>2.南北通透，室内采光极好，让您一进门就感受到家的温暖。<br>3.公用设施有：电视机，洗衣机,冰箱,厨房，wifi,卫生间等，室内干净整洁，设施齐全，可拎包入住。<br>4.小区环境优美，治安良好，让您住的舒适，住的放心。<br>5.周边交通便利，公交地铁路线贯穿东南西北，给您的出行带来极大的方便。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8362da87322a4ff0a9b55067f90a9814.jpg', '["bitehouse/8362da87322a4ff0a9b55067f90a9814.jpg", "bitehouse/9461ea619da145ff98c7a8dd8afd4bf4.jpg"]', 342, '西安', 3149, '雁塔区', '长丰园二区', '3号楼1单元11102室', 108.9401800, 34.1920830);
