INSERT INTO "public"."house" VALUES (61011310074, 1, '省心租·信达雁熙云著西区 3室2厅2卫 独卫', 'worry_free_rental', 12, 30, '3室2厅2卫', 'three', 'south', 25.00, 1200.00, '1.房间装修精美，布局合理，温馨舒适有热水可洗澡。有天然气暖气空调无线WiFi<br>2.南北通透，室内采光极好，让您一进门就感到温暖和温馨，<br>3.公用的设施有洗衣机，厨房，卫生间等等，室内干净，设施齐全，拎包入住<br>4.小区治安良好，干净安全，让您住的安心，放心<br>5.周边交通便捷，地铁公交路线贯穿东西南北，给您的出行带来极大的方便<br>人员要求：1.男女不限,要求无不良嗜好,作息规律，（不能带小孩）<br>2.社会闲杂人士恕不接待,有很差卫生习惯恕不接待,不懂得公共场合秩序,素质差的概不接待!', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9bdfcdc8e2944e479f6fbb8b24e0ae2d.jpg', '["bitehouse/9bdfcdc8e2944e479f6fbb8b24e0ae2d.jpg", "bitehouse/b9cabafc777c4491a8d1c46ac3487ae8.jpg"]', 342, '西安', 3149, '雁塔区', '信达雁熙云著西区', '14号楼2单元21103室', 108.9209150, 34.2181850);
