INSERT INTO "public"."house" VALUES (61011610032, 1, '个人房源·春天花园 3室2厅2卫', 'personal_house', 18, 30, '3室2厅2卫', 'three', 'south', 20.00, 850.00, '各位此房源为合租房源，全西安有房，无任何杂费，无中介费，拎包入住。<br>1.精装全配，有空调暖气，24热水，有厨房，可以做饭。<br>2.房间租住的都是附近上学上班的年轻人，好相处。<br>3.楼下就有公交车站，出行方便。<br>4.房间所产生的水电物业暖气费均由住户均摊，民水民电，用多少买多少。<br>希望即将入住的你讲究卫生，爱干净，并且作息正常，没有小孩，没有宠物，不影响其他人正常休息。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8abc2dfce2f842328fdcbe630e41f614.jpg', '["bitehouse/8abc2dfce2f842328fdcbe630e41f614.jpg", "bitehouse/0e8ecd6859e9408896049bd09e719286.jpg"]', 342, '西安', 3152, '长安区', '春天花园', '4号楼3单元31801室', 108.9069540, 34.1601380);
