INSERT INTO "public"."house" VALUES (61011610034, 1, '省心租·山水怡居高望堆社区南 2室1厅1卫 拎包入住', 'worry_free_rental', 9, 28, '2室1厅1卫', 'two', 'south', 96.00, 2349.00, '社区亮点:周围学校多，中小学幼儿园都有，陪读好房。小区环境优美，治安好，物业管理完善，楼下有地铁站和大超市药店，菜鸟驿站，蔬菜水果，充电桩，设施成熟。<br>房屋亮点：精装全配，房间配套齐全，精装修，南北通透，图片真实，房屋干净整洁，家具家电齐全，无味无甲醛，干净清爽，房间敞亮有地暖，拎包入住。<br>1、热门地段，热门楼层；<br>2、家具家电齐全，空调一级能耗;<br>3、全明格局，客厅宽敞大气;<br>4、户型方正，使用率高达90%，视觉审美不疲劳。<br>5、客厅宽敞舒适、大阳台光线十足<br>6、厨房宽敞，让您和家人有足够的空间展现厨艺.', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f3f99275a90245e9a5eeb121ac5c4557.jpg', '["bitehouse/f3f99275a90245e9a5eeb121ac5c4557.jpg", "bitehouse/e53f2e1b92ed4d30bc069f89cf95dc89.jpg"]', 342, '西安', 3152, '长安区', '山水怡居高望堆社区南', '13号楼2单元20101室', 108.9824060, 34.1633230);
