INSERT INTO "public"."house" VALUES (61011710063, 1, '整租·嘉园蓝湖九郡 2室2厅1卫 拎包入住', 'whole_rent', 19, 20, '2室2厅1卫', 'two', 'south', 95.00, 1700.00, '社区简介：小区环境优雅地理位置优越，门口就是公交站以及泾渭快线，社区自带2000平大型综超，生活购物一应俱全非常方便，更有时尚奶茶店、书店、儿童艺术培训学校等丰富孩子周末学习生活，以及时尚餐吧、饮品店、生鲜蔬菜店、药店等为健康生活保驾护航；小区绿化率高，楼间距大，保证房子充足采光，平时休闲区域开阔，方便您和家人的日常休闲，社区24小时安保巡逻，每个路口、进出口、停车处、入户大厅以及电梯内都有24小时蓄电池红外监控，保证居住安全，是您居住安家的小区之一。', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/9bebfc5f409b41abae6fbe13c7a18cd8.jpg', '["bitehouse/9bebfc5f409b41abae6fbe13c7a18cd8.jpg", "bitehouse/fad8abf032004b8f916158a090d3d141.jpg"]', 342, '西安', 3153, '高陵区', '嘉园蓝湖九郡', '1号楼3单元31701室', 109.0137920, 34.5018230);
