INSERT INTO "public"."house" VALUES (62010010002, 1, '省心租·滩尖子新农村自建房 1室1厅1卫 拎包入住', 'worry_free_rental', 1, 6, '1室1厅1卫', 'one', 'south', 42.00, 1600.00, '1.房东诚心出租，看房方便。<br>2此房为公寓房，独厨独卫，精装修，家具家电齐全，价格700-1800之间，公寓分布整个城关，雁滩，东部，西关，七里河。<br>3、本公司收费为兰州市统一标准，租赁合同签署之后收取首月房租的一般费用', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/e0a40af3879442adb5e900a6bc81e87d.jpg', '["bitehouse/e0a40af3879442adb5e900a6bc81e87d.jpg", "bitehouse/20d5b61acabf406d8e978c4860becaff.jpg"]', 352, '兰州', 3251, '城关区', '滩尖子新农村自建房', '14号楼2单元20103室', 103.8666150, 36.0662450);
