INSERT INTO "public"."house" VALUES (62010010054, 1, '省心租·郑家台80-96号居民楼 1室1厅1卫 可月付', 'worry_free_rental', 2, 6, '1室1厅1卫', 'one', 'south', 30.00, 1050.00, '1、房东诚心出租，看房方便<br>2、超正户型，南北朝向，全明户型，采光好，居住舒服<br>3、小区景色优美，视野开阔，交通便利，物业高端，安全省心<br>4、小区周边生活配套设施齐全，附近有菜市场，大型超市，公交站，地铁站<br>5、房子付款方式不限，可按自身情况自由付款', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/8c81af0f1169497cbba6d1b5b27cf218.jpg', '["bitehouse/8c81af0f1169497cbba6d1b5b27cf218.jpg", "bitehouse/7a869408ecd049958581b1f6203812f1.jpg"]', 352, '兰州', 3251, '城关区', '郑家台80-96号居民楼', '11号楼2单元20202室', 103.8400400, 36.0495490);
