INSERT INTO "public"."house" VALUES (63010010049, 1, '整租·泰和祥花园 2室2厅1卫 拎包入住', 'whole', 1, 33, '2室2厅1卫', 'two', 'east', 102.00, 2900.00, '房间配置齐全交通便利周围购物美食一条街<br>周边配套：银行、酒店、停车场、商场、超市、餐饮<br>1.产权核实真保障：我们认真核实产权的真假信息，为您提供安全保障。<br>2.物业交接真负责：我们认真核实水电气物业等费用是否拖欠，保证您的利益。<br>3.透明交易真落实：房管家房产透明交易，不吃差价，不乱收费。<br>拼搏进取：我们不掌控任何虚假资源，唯有比别人更努力才能取得成功。<br>我们的目标：打造本行业典范，争做全国行业领跑者！！！<br>您的贴心服务专家', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/1ff69dcf493b4324a323e33404cf0a40.jpg', '["bitehouse/1ff69dcf493b4324a323e33404cf0a40.jpg", "bitehouse/10df7b7459d249f5b305c50680ca128a.jpg"]', 366, '西宁', 3340, '城西区', '泰和祥花园', '2号楼2单元20102室', 101.7762600, 36.6290480);
