INSERT INTO "public"."house" VALUES (64010010047, 1, '合租·福泽上豪苑 3室2厅2卫', 'shared', 1, 18, '3室2厅2卫', 'three', 'south', 30.00, 650.00, '月星家居广场，南门，金茂建材城，浙江大厦', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/7198e969ba6c42c88368adc1ae16dc4a.jpg', '["bitehouse/7198e969ba6c42c88368adc1ae16dc4a.jpg", "bitehouse/929896b7fc29469889a666767c21389b.jpg"]', 374, '银川', 3383, '兴庆区', '福泽上豪苑', '13号楼3单元30102室', 106.3028360, 38.4615070);
INSERT INTO "public"."house" VALUES (64010010049, 1, '合租·大地世纪小区 3室2厅2卫', 'shared', 2, 6, '3室2厅2卫', 'three', 'south', 36.00, 460.00, '本公司房源银川均有房源，合租单间，拎包入住，可洗澡做饭。1.[我们承诺]合同截止，到期退押金，不乱收费用！2.[入住须知]合租少4个卧室，没有整租房，男女都有！3.[房屋情况]一户一锁，水电平摊，公用卫生间!4.[房间设施]床衣柜书桌椅子窗帘热水器！5.[室友情况]应届毕业生、白领、企事业员工。6.[租客要求]作息规律，不带老人小孩，多住两人，不养宠物。7.[公司服务]、定期保洁阿姨上门清理卫生，拒绝脏乱差。8.[重要通知]58微聊回复不及时，请直接致电！', 'icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,icebox,washer,heater,broadband,soft,hood,gas,cook,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/a9bbaba2c24041b599e35060a92e6e9e.jpg', '["bitehouse/a9bbaba2c24041b599e35060a92e6e9e.jpg", "bitehouse/eb861004063248308e06cd7622e0f0bf.jpg"]', 374, '银川', 3383, '兴庆区', '大地世纪小区', '20号楼1单元10101室', 106.2574820, 38.4847710);
