INSERT INTO "public"."house" VALUES (64010010055, 1, '个人房源·阅海万家F1区 1室1厅1卫 可月付', 'personal_house', 10, 28, '1室1厅1卫', 'one', 'south', 20.00, 550.00, '房屋介绍<br>无中介费。.<br>二、照片实拍，此图片是房子现有空置房子里的一间！<br>三、单间价格根据大小，<br>从400每月-680每月都有！<br>主卧卫750-800每月都有。<br>四、房子是单间，所有合租房没有单独的厨房和客厅。<br>五、房子基础设施：电梯WiFi、密码锁、洗衣机、热水器、保洁、1.5米床、衣柜、桌椅、全身镜、晾衣架、沙发茶几。<br>六、月付不讲价，季度付、半年付可适当优惠。', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/d44a47af871c4787a1e8e537fd186a51.jpg', '["bitehouse/d44a47af871c4787a1e8e537fd186a51.jpg", "bitehouse/dee858887c614e21aa98d0b5e6e1da4a.jpg"]', 374, '银川', 3385, '金凤区', '阅海万家F1区', '17号楼2单元20104室', 106.2568410, 38.5172770);
