INSERT INTO "public"."house" VALUES (64010010058, 1, '省心租·阅海万家F2区 3室2厅1卫', 'worry_free_rental', 26, 28, '3室2厅1卫', 'three', 'south', 25.00, 680.00, '1：，不收取任何形式的维管费和中介费，房东亲自服务，所有东西免费维修！住够时间保证退押金！<br>2：房子在阅海万家F2区。<br>3：全屋精装修，木地板、1.8米双人大床、配厚床垫、床头柜、衣柜、鞋柜、高档窗帘、穿衣镜、写字桌、写字椅、（部分房间配沙发，茶几、藤椅，圆桌），卫生间配电热水器，可以24小时洗热水澡，全自动洗衣机、WIFI。', 'tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating,tv,aircondition,wardrobe,bed,toilet,smartlock,balcony,heating', 'bitehouse/f8546c603656449c9371f5719f9c1d65.jpg', '["bitehouse/f8546c603656449c9371f5719f9c1d65.jpg", "bitehouse/bcefb553e86a47298c6c660030380335.jpg"]', 374, '银川', 3385, '金凤区', '阅海万家F2区', '19号楼3单元31101室', 106.2636170, 38.5179270);
